<template>
  <section ref="managerMenu">
    <div class="row">
      <!-- Modal -->
      <div
        class="modal fade"
        id="staticBackdrop"
        data-bs-backdrop="static"
        data-bs-keyboard="false"
        tabindex="1"
        aria-labelledby="staticBackdropLabel"
        aria-hidden="false"
      >
        <div class="modal-dialog">
          <div class="modal-content">
            <div class="modal-header nxp-light-gray">
              <h5 class="modal-title" id="exampleModalLabel">
                Change motor description: {{ fileName }}
              </h5>
              <button
                type="button"
                class="btn-close"
                data-bs-dismiss="modal"
                aria-label="Close"
              ></button>
            </div>
            <div class="modal-body">
              <form>
                <div class="mb-3">
                  <label for="motor-id" class="col-form-label">Motor ID:</label>
                  <input
                    type="text"
                    class="form-control text-start"
                    id="motor-id"
                    maxlength="40"
                    :placeholder="motorId"
                    @input="count('motor-id')"
                    v-model="newId"
                  />
                  <div> Characters remaining: <mark class="green"> {{ idCharacters }} </mark></div>
                </div>
                <div class="mb-3">
                  <label for="motor-description" class="col-form-label"
                    >Descripion:</label
                  >
                  <textarea
                    class="form-control resize-none"
                    id="motor-description"
                    maxlength="200"
                    @input="count('motor-description')"
                    :placeholder="motorDescription"
                    v-model="newDescription"
                  />
                  <div> Characters remaining: <mark class="green"> {{ descriptionCharacters }} </mark></div>
                </div>
              </form>
            </div>
            <div class="modal-footer nxp-light-gray">
              <button
                type="button"
                class="btn nxp-orange"
                data-bs-dismiss="modal"
              >
                Close
              </button>
              <button
                type="button"
                class="btn nxp-light-blue"
                data-bs-dismiss="modal"
                @click="update"
              >
                OK
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
    <div class="row">
      <div class="col-md-3 mx-auto" v-for="column in columns" :key="column.id">
        <div class="row flex-nowrap">
          <div class="col" v-if="column.hasDropdown">
            <div class="dropdown text-end">
              <button
                :class="
                  'btn ' + column.dropdown.color + ' btn-md dropdown-toggle text-nowrap'
                "
                type="button"
                :ref="column.dropdown.id"
                data-bs-toggle="dropdown"
                aria-haspopup="true"
                aria-expanded="false"
              >
                {{ column.dropdown.placeholder }}
              </button>
              <div class="dropdown-menu" aria-labelledby="dropdownMenuButton">
                <a
                  :class="'dropdown-item ' + option.disabled"
                  href="#"
                  v-for="option in column.dropdown.options"
                  :key="option.id"
                  :ref="option.id"
                  :title="option.motorId"
                  :data-bs-toggle="option.dataToggle"
                  :data-bs-target="option.dataTarget"
                  @click="setDropdownValue(option)"
                >
                  {{ option.text }}
                </a>
              </div>
            </div>
          </div>
          <div class="col-3" v-else>
          </div>
          <div class="col">
            <button
              :class="column.button.className"
              :ref="column.button.id"
              :disabled="column.button.disabled"
              @click="clickButton(column.button.id)"
            >
              <i :class="column.button.iconName"></i>
              {{ column.button.label }}
            </button>
          </div>
        </div>
      </div>
    </div>
  </section>
</template>
<script>
export default {
  name: "ManagerMenu",
  props: ["inFiles"],
  data() {
    return {
      descriptionCharacters: 200,
      idCharacters: 40,
      fileName: "",
      newDescription: "",
      newId: "",
      motorId: "",
      motorDescription: "",
      columns: [
        {
          id: "column1",
          hasDropdown: true,
          button: {
            id: "loadFileButton",
            className: "btn btn-md nxp-orange text-nowrap",
            iconName: "fas fa-sync",
            label: "Load data",
            disabled: true,
          },
          dropdown: {
            id: "inputFileList",
            color: "nxp-orange",
            placeholder: "Choose input file...",
            options: [
              {
                id: "inFile1",
                text: "m1_pmsm_appconfig.h",
                disabled: "disabled",
                motorId: "lorem ipsum dolor sit amet",
                motorDescription: "",
                dataToggle: "",
                dataTarget: "",
              },
              {
                id: "inFile2",
                text: "m2_pmsm_appconfig.h",
                disabled: "disabled",
                motorId: "lorem ipsum dolor sit amet",
                motorDescription: "",
                dataToggle: "",
                dataTarget: "",
              },
              {
                id: "inFile3",
                text: "m3_pmsm_appconfig.h",
                disabled: "disabled",
                motorId: "lorem ipsum dolor sit amet",
                motorDescription: "",
                dataToggle: "",
                dataTarget: "",
              },
              {
                id: "inFile4",
                text: "m4_pmsm_appconfig.h",
                disabled: "disabled",
                motorId: "lorem ipsum dolor sit amet",
                motorDescription: "",
                dataToggle: "",
                dataTarget: "",
              },
              {
                id: "inFile5",
                text: "m5_pmsm_appconfig.h",
                disabled: "disabled",
                motorId: "lorem ipsum dolor sit amet",
                motorDescription: "",
                dataToggle: "",
                dataTarget: "",
              },
              {
                id: "inFile6",
                text: "m6_pmsm_appconfig.h",
                disabled: "disabled",
                motorId: "lorem ipsum dolor sit amet",
                motorDescription: "",
                dataToggle: "",
                dataTarget: "",
              },
              {
                id: "inFile7",
                text: "m7_pmsm_appconfig.h",
                disabled: "disabled",
                motorId: "lorem ipsum dolor sit amet",
                motorDescription: "",
                dataToggle: "",
                dataTarget: "",
              },
              {
                id: "inFile8",
                text: "m8_pmsm_appconfig.h",
                disabled: "disabled",
                motorId: "lorem ipsum dolor sit amet",
                motorDescription: "",
                dataToggle: "",
                dataTarget: "",
              },
              {
                id: "inFile9",
                text: "m9_pmsm_appconfig.h",
                disabled: "disabled",
                motorId: "lorem ipsum dolor sit amet",
                motorDescription: "",
                dataToggle: "",
                dataTarget: "",
              },
            ],
          },
        },
        {
          id: "column2",
          hasDropdown: true,
          button: {
            id: "saveFileButton",
            label: "Save data",
            className: "btn btn-md nxp-light-blue text-nowrap",
            iconName: "fas fa-file-export",
            disabled: true,
          },
          dropdown: {
            id: "outputFileList",
            color: "nxp-light-blue",
            placeholder: "Choose output file...",
            options: [
              {
                id: "outFile1",
                text: "m1_pmsm_appconfig.h",
                disabled: "nxp-light-gray",
                motorId: "",
                motorDescription: "",
                dataToggle: "modal",
                dataTarget: "#staticBackdrop",
              },
              {
                id: "outFile2",
                text: "m2_pmsm_appconfig.h",
                disabled: "nxp-light-gray",
                motorId: "",
                motorDescription: "",
                dataToggle: "modal",
                dataTarget: "#staticBackdrop",
              },
              {
                id: "outFile3",
                text: "m3_pmsm_appconfig.h",
                disabled: "nxp-light-gray",
                motorId: "",
                motorDescription: "",
                dataToggle: "modal",
                dataTarget: "#staticBackdrop",
              },
              {
                id: "outFile4",
                text: "m4_pmsm_appconfig.h",
                disabled: "nxp-light-gray",
                motorId: "",
                motorDescription: "",
                dataToggle: "modal",
                dataTarget: "#staticBackdrop",
              },
              {
                id: "outFile5",
                text: "m5_pmsm_appconfig.h",
                disabled: "nxp-light-gray",
                motorId: "",
                motorDescription: "",
                dataToggle: "modal",
                dataTarget: "#staticBackdrop",
              },
              {
                id: "outFile6",
                text: "m6_pmsm_appconfig.h",
                disabled: "nxp-light-gray",
                motorId: "",
                motorDescription: "",
                dataToggle: "modal",
                dataTarget: "#staticBackdrop",
              },
              {
                id: "outFile7",
                text: "m7_pmsm_appconfig.h",
                disabled: "nxp-light-gray",
                motorId: "",
                motorDescription: "",
                dataToggle: "modal",
                dataTarget: "#staticBackdrop",
              },
              {
                id: "outFile8",
                text: "m8_pmsm_appconfig.h",
                disabled: "nxp-light-gray",
                motorId: "",
                motorDescription: "",
                dataToggle: "modal",
                dataTarget: "#staticBackdrop",
              },
              {
                id: "outFile9",
                text: "m9_pmsm_appconfig.h",
                disabled: "nxp-light-gray",
                motorId: "",
                motorDescription: "",
                dataToggle: "modal",
                dataTarget: "#staticBackdrop",
              },
            ],
          },
        },
        {
          id: "column3",
          hasDropdown: false,
          button: {
            id: "updateTargetButton",
            label: "Update target",
            className: "btn btn-md nxp-green text-nowrap",
            iconName: "fas fa-share-square",
            disabled: false,
          },
        },
      ],
    };
  },
  methods: {
    setDropdownValue(option) {
      const id = option.id;
      const text = option.text;
      const description = option.motorDescription;
      const motorId = option.motorId
      if (id.startsWith("out")) {
        this.columns[1].dropdown.placeholder = text;
        this.columns[1].button.disabled = false;
        this.motorId = motorId;
        this.motorDescription = description;
        this.fileName = text;
        this.newId = option.motorId;
        this.newDescription = option.motorDescription;
      } else if (id.startsWith("in")) {
        this.columns[0].dropdown.placeholder = text;
        this.columns[0].button.disabled = false;
      }
    },
    clickButton(id) {
      const buttonsData = {
        updateTargetButton: "",
        saveFileButton: this.columns[1].dropdown.placeholder,
        loadFileButton: this.columns[0].dropdown.placeholder,
      };
      this.$emit("button-manager-was-clicked", [id, buttonsData[id]]);
    },
    count(id) {
      const ids = {
        "motor-id": () => {
          this.idCharacters = 40 - this.newId.length
        },
        "motor-description": () => {
          this.descriptionCharacters = 200 - this.newDescription.length;
        }
      }
      ids[id]();      
    },
    update() {
      // this.newId = this.motorId;
      // this.newDescription = this.motorDescription;
      const outFiles = this.columns[1].dropdown.options;
      outFiles.forEach((file) => {
        if (file.text === this.fileName) {
          file.motorId = this.newId;
          file.motorDescription = this.newDescription;
          this.$emit("motor-description-changed", [this.fileName, this.newId, this.newDescription]);
        }
      });
    }
  },
  watch: {
    inFiles: function (newVal) {
      if (newVal !== "") {
        const name = newVal.name;
        const motorId = newVal.motorId;
        const description = newVal.description;
        const inFiles = this.columns[0].dropdown.options;
        const outFiles = this.columns[1].dropdown.options;
        inFiles.forEach((inFile) => {
          if (inFile.text === name) {
            inFile.disabled = "";
            inFile.motorId = motorId;
            inFile.motorDescription = description;
          }
        });
        outFiles.forEach((out) => {
          if (out.text === name) {
            out.disabled = "";
            out.motorId = motorId;
            out.motorDescription = description
          }
        });
      }
    },
  },
};
</script>

