const constants = require("./numeralConstants");
import { checkIfParamsAreNumbers } from "../logic/utils";


/**
 * calculate M1_SERVO_POSITION_P_PROP_GAIN - Position loop P controller proportional gain
 * @param {object} inputStructure 
 * @returns {number}
 */
function m1_servo_position_p_prop_gain(inputStructure) {

    const positionLoopF0 = inputStructure.positionLoop.positionLoopF0; // Position loop bandwidth
    const positionLoopKsi = inputStructure.positionLoop.positionLoopKsi; // Position loop attenuation
    const parametersPp = inputStructure.parameters.parametersPp; // Number of pole-pairs
    var k10 = 1/(2*Math.PI*parametersPp); // Output from encoder is mechanical speed, needed recomputation to angular electrical speed
    var k12 = 1.0;
    var ret; // Return value

    // w0 = 2*pi*f0 - bandwidth [rad/s]
    // kp_fi = (kk*w0)/(k10*k12*(2*ksi*kk+1)) - in S-domain
    // M1_POSITION_P_PROP_GAIN = (parametersKk * (2 * pi * speedLoopF0))/( (2 * speedLoopKsi * parametersKk + 1) * k10*k12) - in Z-domain
    checkIfParamsAreNumbers([positionLoopF0, positionLoopKsi, k10], (isValid) => {
        ret = isValid ? (  (constants.parametersKk * (2 * Math.PI * positionLoopF0))/( (2 * positionLoopKsi * constants.parametersKk + 1) * k10*k12)  ) : NaN;     
        });
    return ret;


}

/**
 * calculate M1_SERVO_POSITION_P_HIGH_LIMIT - Position loop P controller output maximal limit (output is electrical angular speed)
 * @param {object} inputStructure 
 * @returns {number}
 */
function m1_servo_position_p_high_limit(inputStructure) {

    const positionPControllerHighLimit = inputStructure.positionLoop.servo_positionLoopUpperLimit; //Position P controller output high limit in RPM
    const parametersPp = inputStructure.parameters.parametersPp; // Number of pole-pairs
    var ret; // Return value

    // 2*pi*positionPControllerHighLimit*pp/60 - recomputed speed from RPM to electrical angular speed. 
    checkIfParamsAreNumbers([positionPControllerHighLimit, parametersPp], (isValid) => {
        ret = isValid ? ( 2 * Math.PI * positionPControllerHighLimit * parametersPp / 60.0 ) : NaN;     
        });
    return ret;

}

/**
 * calculate M1_SERVO_POSITION_P_LOW_LIMIT - Position loop P controller output minimal limit (output is electrical angular speed)
 * @param {object} inputStructure 
 * @returns {number}
 */
function m1_servo_position_p_low_limit(inputStructure) {

    const positionPControllerLowLimit = inputStructure.positionLoop.servo_positionLoopLowerLimit; //Position P controller output high limit in RPM
    const parametersPp = inputStructure.parameters.parametersPp; // Number of pole-pairs
    var ret; // Return value

    // 2*pi*positionPControllerLowLimit*pp/60 - recomputed speed from RPM to electrical angular speed. 
    checkIfParamsAreNumbers([positionPControllerLowLimit, parametersPp], (isValid) => {
        ret = isValid ? ( 2 * Math.PI * positionPControllerLowLimit * parametersPp / 60.0 ) : NaN;     
        });
    return ret;

}

/**
 * calculate M1_SERVO_FEED_FRWD_K1 - Position loop feed forward k1 constant
 * @param {object} inputStructure 
 * @returns {number}
 */
function m1_servo_feed_frwd_k1(inputStructure) {
    const positionLoopF0 = inputStructure.positionLoop.positionLoopF0; // Position loop bandwidth
    const positionLoopKsi = inputStructure.positionLoop.positionLoopKsi; // Position loop attenuation
    var k_feed = 1.0; // Feed forward gain
    var kp_fi = m1_servo_position_p_prop_gain(inputStructure); // Position loop P controller proportional gain
    var ret; // Return value

    // w0 = 2*pi*f0 - bandwidth [rad/s]
    // k1 = 2*ksi*kp_fi/(k_feed*w0)
    checkIfParamsAreNumbers([positionLoopF0, positionLoopKsi], (isValid) => {
        ret = isValid ? ( 2*positionLoopKsi*kp_fi/(k_feed* (2 * Math.PI * positionLoopF0)) ) : NaN;     
        });
    return ret;
}

/**
 * calculate M1_SERVO_FEED_FRWD_K2 - Position loop feed forward k2 constant
 * @param {object} inputStructure 
 * @returns {number}
 */
function m1_servo_feed_frwd_k2(inputStructure) {
    const positionLoopF0 = inputStructure.positionLoop.positionLoopF0; // Position loop bandwidth
    var k_feed = 1.0; // Feed forward gain
    var kp_fi = m1_servo_position_p_prop_gain(inputStructure); // Position loop P controller proportional gain
    var ret; // Return value

    // w0 = 2*pi*f0 - bandwidth [rad/s]
    // k2 = kp_fi/(k_feed*w0*w0)
    checkIfParamsAreNumbers([positionLoopF0], (isValid) => {
        ret = isValid ? ( kp_fi/(k_feed*(2*Math.PI*positionLoopF0)*(2*Math.PI*positionLoopF0)) ) : NaN;     
        });
    return ret;
}

/**
 * calculate M1_SERVO_IIR_ZC_B0 - Zero cancellation filter B0 coeficient
 * @param {object} inputStructure 
 * @returns {number}
 */
function m1_servo_iir_zc_b0(inputStructure) {
    
    const positionLoopSampleTime = inputStructure.positionLoop.positionLoopSampleTime; // Position loop sample time
    const positionLoopF0 = inputStructure.positionLoop.positionLoopF0; // Position loop bandwidth
    const positionLoopKsi = inputStructure.positionLoop.positionLoopKsi; // Position loop attenuation
    var Tfilt = (2*positionLoopKsi + constants.parametersKk)/((2*positionLoopKsi*constants.parametersKk + 1)*2*Math.PI*positionLoopF0); // Ti = 1/ki = (2*ksi+kk)/((2*ksi*kk+1)*w0)
    var ret; 

    // M1_SPEED_IIR_B0_ZC = speedLoopSampleTime / (speedLoopSampleTime + 2 * Tfilt )
    checkIfParamsAreNumbers([positionLoopSampleTime, Tfilt], (isValid) => {
        ret = isValid ? ( positionLoopSampleTime/(positionLoopSampleTime + 2 * Tfilt) ) : NaN;     
        });
    return ret;
}

/**
 * calculate M1_SERVO_IIR_ZC_B1 - Zero cancellation filter B1 coeficient
 * @param {object} inputStructure 
 * @returns {number}
 */
function m1_servo_iir_zc_b1(inputStructure) {
    
    const positionLoopSampleTime = inputStructure.positionLoop.positionLoopSampleTime; // Position loop sample time
    const positionLoopF0 = inputStructure.positionLoop.positionLoopF0; // Position loop bandwidth
    const positionLoopKsi = inputStructure.positionLoop.positionLoopKsi; // Position loop attenuation
    var Tfilt = (2*positionLoopKsi + constants.parametersKk)/((2*positionLoopKsi*constants.parametersKk + 1)*2*Math.PI*positionLoopF0); // Ti = 1/ki = (2*ksi+kk)/((2*ksi*kk+1)*w0)
    var ret; 

    // M1_SPEED_IIR_B1_ZC = speedLoopSampleTime / (speedLoopSampleTime + 2 * Tfilt )
    checkIfParamsAreNumbers([positionLoopSampleTime, Tfilt], (isValid) => {
        ret = isValid ? ( positionLoopSampleTime/(positionLoopSampleTime + 2 * Tfilt) ) : NaN;     
        });
    return ret;
}

/**
 * calculate M1_SERVO_IIR_ZC_A1 - Zero cancellation filter A1 coeficient
 * @param {object} inputStructure 
 * @returns {number}
 */
function m1_servo_iir_zc_a1(inputStructure) {
    const positionLoopSampleTime = inputStructure.positionLoop.positionLoopSampleTime; // Position loop sample time
    const positionLoopF0 = inputStructure.positionLoop.positionLoopF0; // Position loop bandwidth
    const positionLoopKsi = inputStructure.positionLoop.positionLoopKsi; // Position loop attenuation
    var Tfilt = (2*positionLoopKsi + constants.parametersKk)/((2*positionLoopKsi*constants.parametersKk + 1)*2*Math.PI*positionLoopF0); // Ti = 1/ki = (2*ksi+kk)/((2*ksi*kk+1)*w0)
    var ret; 

    // M1_SPEED_IIR_A1_ZC = -(speedLoopSampleTime - 2 * Tfilt) / (speedLoopSampleTime + 2 * Tfilt )
    checkIfParamsAreNumbers([positionLoopSampleTime, Tfilt], (isValid) => {
        ret = isValid ? ( (-1)*(positionLoopSampleTime - 2*Tfilt)/(positionLoopSampleTime + 2*Tfilt) ) : NaN;     
        });
    return ret;
}

/**
 * calculate M1_SERVO_SPEED_PI_PROP_GAIN - Servo control - Speed loop PI controller proportional gain
 * @param {object} inputStructure 
 * @returns {number}
 */
function m1_servo_speed_pi_prop_gain(inputStructure) {

    const positionLoopSampleTime = inputStructure.positionLoop.positionLoopSampleTime; // Position loop sample time
    const positionLoopF0 = inputStructure.positionLoop.positionLoopF0; // Position loop bandwidth
    const positionLoopKsi = inputStructure.positionLoop.positionLoopKsi; // Position loop attenuation
    const parametersJ = inputStructure.parameters.parametersJ; // Inertia
    const parametersPp = inputStructure.parameters.parametersPp; // Number of pole-pairs
    const parametersKt = inputStructure.parameters.parametersKt; // Torque constant
    var ret; // Return value

    // w0 = 2*pi*f0 - bandwidth [rad/s]
    // kp_w = w0*(2*ksi+kk)*J/(kt*pp) - in S-domain
    // M1_SPEED_PI_PROP_GAIN = ((2 * speedLoopKsi + parametersKk) * (2 * pi * speedLoopF0) * parametersJ) / (parametersKt*pp) - in Z-domain
    checkIfParamsAreNumbers([positionLoopSampleTime, positionLoopF0, positionLoopKsi, parametersJ, parametersPp, parametersKt ], (isValid) => {
        ret = isValid ? ( ((2 * positionLoopKsi + constants.parametersKk) * (2 * Math.PI * positionLoopF0) * parametersJ) / (parametersKt * parametersPp) ) : NaN;     
        });
    return ret;

}

/**
 * calculate M1_SERVO_SPEED_PI_INTEG_GAIN - Servo control - Speed loop PI controller integration gain
 * @param {object} inputStructure 
 * @returns {number}
 */
function m1_servo_speed_pi_integ_gain(inputStructure) {

    const positionLoopSampleTime = inputStructure.positionLoop.positionLoopSampleTime; // Position loop sample time
    const positionLoopF0 = inputStructure.positionLoop.positionLoopF0; // Position loop bandwidth
    const positionLoopKsi = inputStructure.positionLoop.positionLoopKsi; // Position loop attenuation
    const parametersJ = inputStructure.parameters.parametersJ; // Inertia
    const parametersPp = inputStructure.parameters.parametersPp; // Number of pole-pairs
    const parametersKt = inputStructure.parameters.parametersKt; // Torque constant
    var ret; // Return value

    // w0 = 2*pi*f0 - bandwidth [rad/s]
    // kp_w = ((2*ksi*kk+1)*w0*w0*J)/(kt*pp) - in S-domain
    // M1_SPEED_PI_INTEG_GAIN = ((parametersJ * (2 * speedLoopKsi * parametersKk + 1) * (2 * pi * speedLoopF0) * (2 * pi * speedLoopF0)) / (parametersKt*pp) ) * (speedLoopSampleTime / 2) - in Z-domain
    checkIfParamsAreNumbers([positionLoopSampleTime, positionLoopF0, positionLoopKsi, parametersJ, parametersPp, parametersKt ], (isValid) => {
        ret = isValid ? ( ((parametersJ * (2 * positionLoopKsi * constants.parametersKk + 1) * (2 * Math.PI * positionLoopF0) * (2 * Math.PI * positionLoopF0)) / (parametersKt*parametersPp) ) * (positionLoopSampleTime / constants.DiscMethodFactor)  ) : NaN;     
        });
    return ret;

}

/**
 * export function calculates the whole parameters output structure
 * @param {object} inputStructure 
 * @returns {object}
 */
export function calculateParams(inputStructure) {
    return {
        M1_SERVO_POSITION_P_PROP_GAIN: m1_servo_position_p_prop_gain(inputStructure),
        M1_SERVO_POSITION_P_HIGH_LIMIT: m1_servo_position_p_high_limit(inputStructure),
        M1_SERVO_POSITION_P_LOW_LIMIT: m1_servo_position_p_low_limit(inputStructure),
        M1_SERVO_FEED_FRWD_K1: m1_servo_feed_frwd_k1(inputStructure),
        M1_SERVO_FEED_FRWD_K2: m1_servo_feed_frwd_k2(inputStructure),
        M1_SERVO_IIR_ZC_B0: m1_servo_iir_zc_b0(inputStructure),
        M1_SERVO_IIR_ZC_B1: m1_servo_iir_zc_b1(inputStructure),
        M1_SERVO_IIR_ZC_A1: m1_servo_iir_zc_a1(inputStructure),
        M1_SERVO_SPEED_PI_PROP_GAIN: m1_servo_speed_pi_prop_gain(inputStructure),
        M1_SERVO_SPEED_PI_INTEG_GAIN: m1_servo_speed_pi_integ_gain(inputStructure),
        //M1_SERVO_SPEED_PI_HIGH_LIMIT: m1_servo_speed_pi_high_limit(inputStructure),
        //M1_SERVO_SPEED_PI_LOW_LIMIT: m1_servo_speed_pi_low_limit(inputStructure)

    }
}
