<template>
  <section ref="parametersCanvas" v-if="visible">
    <div class="alert alert-warning" v-if="isWarning">
      <strong>Warning! </strong>
      <slot> {{ warningMessage }}</slot>
    </div>
    <div class="alert alert-danger" v-if="isWrong">
      <strong>Error! </strong>
      <slot> {{ errorMessage }}</slot>
    </div>
    <div class="row">
      <div class="col border-end" v-for="column in columns" :key="column.index">
        <div v-for="section in column.sections" :key="section.name">
          <hr />
          <span class="text-uppercase fw-bold">
            {{ section.name }}
          </span>
          <div class="row m-1" v-for="item in section.fields" :key="item.id" :title="item.hint">
            <div class="col-4 d-flex align-items-center justify-content-end">
              <label :for="item.id"> {{ item.label }}: </label>
            </div>
            <div class="col-4">
              <input :class="'form-control ' + item.className" autocomplete="off" :ref="item.id"
                :disabled="item.disabled" v-model.number="item.value" :type="item.type"
                @keyup.enter="$event.target.blur()" @blur="sendValue(item.id, item.value, true)" />
            </div>
            <div class="col-1 d-flex align-items-center justify-content-start">
              <label v-if="item.hasUnit" :for="item.id" v-html="'[' + item.unit + ']'">
              </label>
            </div>
          </div>
          <hr />
        </div>
      </div>
      <hr />
    </div>
  </section>
</template>

<script>
import { getFieldById } from "../logic/utils";
import { toBaseValue, setFieldFromBaseValue, addPrefixToUnit } from "../functions/scalingConfig";
export default {
  name: "ParametersCanvas",
  props: ["visible", "needData", "parametersOutputs", "reloadData", "limits"],
  data() {
    return {
      isWrong: false,
      isWarning: false,
      warningMessage: "",
      errorMessage: "",
      columns: [
        {
          index: "column1",
          sections: [
            {
              name: "Motor parameters",
              fields: [
                {
                  type: "input",
                  id: "parametersPp",
                  className: "",
                  label: "Pp",
                  unit: "-",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Motor number of pole-pairs.",
                  validation: {
                    type: "number",
                    isFloat: false,
                    minRange: 1,
                    maxRange: 50,
                  },
                },
                {
                  type: "input",
                  id: "parametersRs",
                  className: "",
                  label: "Rs",
                  unit: "Ω",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Stator phase resistance.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.001,
                    maxRange: 500.0,
                  },
                },
                {
                  type: "input",
                  id: "parametersLd",
                  className: "",
                  label: "Ld",
                  unit: "H",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Stator direct inductance.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.000001,
                    maxRange: 1.0,
                  },
                },
                {
                  type: "input",
                  id: "parametersLq",
                  className: "",
                  label: "Lq",
                  unit: "H",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Stator quadrature inductance.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.000001,
                    maxRange: 1.0,
                  },
                },
                {
                  type: "input",
                  id: "parametersKt",
                  className: "",
                  label: "Kt",
                  unit: "Nm/Amp",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Motor torque constant.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 1.0,
                    maxRange: 1000.0,
                  },
                },
                {
                  type: "input",
                  id: "parametersJ",
                  className: "",
                  label: "J",
                  unit: "g∙m^2",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Drive inertia.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.000001,
                    maxRange: 10.0,
                  },
                },
                {
                  type: "input",
                  id: "parametersIphNom",
                  className: "",
                  label: "Iph nom",
                  unit: "A",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Nominal current.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.001,
                    maxRange: "",
                  },
                },
                {
                  type: "input",
                  id: "parametersUphNom",
                  className: "",
                  label: "Uph nom",
                  unit: "V",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Nominal voltage.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 1.0,
                    maxRange: "",
                  },
                },
                {
                  type: "input",
                  id: "parametersNnom",
                  className: "",
                  label: "N nom",
                  unit: "rpm",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Nominal speed.",
                  validation: {
                    type: "number",
                    isFloat: false,
                    minRange: 1,
                    maxRange: "",
                  },
                },
              ],
            },
            {
              name: "Hardware scales",
              fields: [
                {
                  type: "input",
                  id: "parametersImax",
                  className: "",
                  label: "I max",
                  unit: "A",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Current sensing HW scale.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.1,
                    maxRange: 100.0,
                  },
                },
                {
                  type: "input",
                  id: "parametersUdcbMax",
                  className: "",
                  label: "U DCB max",
                  unit: "V",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "DCbus voltage sensing HW scale.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 1,
                    maxRange: 1000,
                  },
                },
              ],
            },
          ],
        },
        {
          index: "column2",
          sections: [
            {
              name: "Fault limits",
              fields: [
                {
                  type: "input",
                  id: "parametersUdcbTrip",
                  className: "",
                  label: "U DCB trip",
                  unit: "V",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "DCbus braking resistor threshold.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: "",
                  },
                },
                {
                  type: "input",
                  id: "parametersUdcbUnder",
                  className: "",
                  label: "U DCB under",
                  unit: "V",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "DCbus under voltage fault threshold.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: "",
                  },
                },
                {
                  type: "input",
                  id: "parametersUdcbOver",
                  className: "",
                  label: "U DCB over",
                  unit: "V",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "DCbus over voltage fault threshold.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: "",
                  },
                },
                {
                  type: "input",
                  id: "parametersNover",
                  className: "",
                  label: "N over",
                  unit: "rpm",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Over speed fault threshold.",
                  validation: {
                    type: "number",
                    isFloat: false,
                    minRange: "",
                    maxRange: "",
                  },
                },
                {
                  type: "input",
                  id: "parametersNmin",
                  className: "",
                  label: "N min",
                  unit: "rpm",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Minimal closed loop speed.",
                  validation: {
                    type: "number",
                    isFloat: false,
                    minRange: 0,
                    maxRange: "",
                  },
                },
                {
                  type: "input",
                  id: "parametersEblock",
                  className: "",
                  label: "E block",
                  unit: "V",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Blocked rotor detection Bemf voltage level.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.1,
                    maxRange: "",
                  },
                },
                {
                  type: "input",
                  id: "parametersEblockPer",
                  className: "",
                  label: "E block per",
                  unit: "V",
                  disabled: false,
                  value: "",
                  hasUnit: false,
                  hint: "Number of period to set blocked rotor fault.",
                  validation: {
                    type: "number",
                    isFloat: false,
                    minRange: 0,
                    maxRange: 50000,
                  },
                },
              ],
            },
            {
              name: "Application scales",
              fields: [
                {
                  type: "input",
                  id: "parametersNmax",
                  className: "",
                  label: "N max",
                  unit: "rpm",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Application speed scale.",
                  validation: {
                    type: "number",
                    isFloat: false,
                    minRange: 0,
                    sampleTime: "",
                    maxRange: "",
                  },
                },
                {
                  type: "input",
                  id: "parametersUdcbIIRf0",
                  className: "",
                  label: "U DCB IIR F0",
                  unit: "Hz",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Cut-off frequency of DCbus IIR filter.",
                  validation: {
                    type: "number",
                    isFloat: false,
                    minRange: 0,
                    maxRange: 1000,
                  },
                },
                {
                  type: "input",
                  id: "parametersCalibDuration",
                  className: "",
                  label: "Calibration duration",
                  unit: "sec",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Motor calibration duration.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0,
                    maxRange: "5.0",
                  },
                },
                {
                  type: "input",
                  id: "parametersFaultDuration",
                  className: "",
                  label: "Fault duration",
                  unit: "sec",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "After fault condition ends wait defined time to clear fault state.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0,
                    maxRange: 10.0,
                  },
                },
                {
                  type: "input",
                  id: "parametersFreewheelDuration",
                  className: "",
                  label: "Freewheel duration",
                  unit: "sec",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Free-wheel duration set-up.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0,
                    maxRange: 100.0,
                  },
                },
                {
                  type: "input",
                  id: "parametersScalarUqMin",
                  className: "",
                  label: "Scalar Uq min",
                  unit: "V",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Scalar control voltage bias.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: "",
                  },
                },
                {
                  type: "input",
                  id: "parametersScalarVHzRatio",
                  className: "",
                  label: "Scalar V/Hz factor ratio",
                  unit: "%",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Scalar V/Hz factor gain ratio.",
                  validation: {
                    type: "number",
                    isFloat: false,
                    minRange: 50,
                    maxRange: 200,
                  },
                },               
              ],
            },
            {
              name: "Alignment",
              fields: [
                {
                  type: "input",
                  id: "parametersAlignVoltage",
                  className: "",
                  label: "Align voltage",
                  unit: "V",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Motor alignment voltage.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0,
                    maxRange: "",
                  },
                },
                {
                  type: "input",
                  id: "parametersAlignDuration",
                  className: "",
                  label: "Align duration",
                  unit: "sec",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Motor alignment duration.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 10.0,
                  },
                },
              ],
            },
          ],
        },
      ],
    };
  },
  methods: {
    /**
     * simplifies grid structure for data manipulation. If new *section* is added / deleted it has to be manually changed
     * @param {none}
     * @returns {object} grid data divided into input / output group
     */
    getData() {
      const column1 = this.columns[0].sections;
      const column2 = this.columns[1].sections;
      const motorParametersData = column1[0].fields;
      const hardwareScalesData = column1[1].fields;
      const faultLimitsData = column2[0].fields;
      const applicationScalesData = column2[1].fields;
      const alignmentData = column2[2].fields;
      return {
        input: {
          motorParametersData,
          hardwareScalesData,
          faultLimitsData,
          applicationScalesData,
          alignmentData,
        },
      };
    },
    /**
     * sets a value to a specific field given an id
     * @param {string} id
     * @param {number} baseValue
     * @returns {none}
     */
    setData(id, baseValue) {
      const thisRef = this;
      getFieldById(id, this.getData(), (field) => {
        setFieldFromBaseValue(field, baseValue);
        thisRef.setLimits(id, baseValue);
      });
    },
    setLimits(id, value) {
      const data = this.getData();
      const setRange = function (id, value) {
        const ranges = {
          parametersImax: function () {
            data.input.motorParametersData[6].validation.maxRange = value;
          },
          parametersUdcbMax: function () {
            data.input.motorParametersData[7].validation.maxRange = value / 2;
            data.input.faultLimitsData[0].validation.maxRange = value;
            data.input.faultLimitsData[1].validation.maxRange = value;
            data.input.faultLimitsData[2].validation.maxRange = value;
            data.input.faultLimitsData[5].validation.maxRange = value / 2;
            data.input.applicationScalesData[5].validation.maxRange = value / 2;
            data.input.alignmentData[0].validation.maxRange = value / 2;
          },
          parametersNmax: function () {
            data.input.motorParametersData[8].validation.maxRange = value;
            data.input.faultLimitsData[3].validation.maxRange = value;
          },
          parametersNmin: function () {
            data.input.faultLimitsData[3].validation.minRange = value;
          },
          parametersPp: function () {
            const nMax = data.input.applicationScalesData[0];
            nMax.validation.maxRange =
              ((1 / nMax.validation.sampleTime) * 60) / 10 / value;
          },
          parametersNover: function () {
            data.input.faultLimitsData[4].validation.maxRange = value;
          },
        };
        return Object.keys(ranges).find((key) => {
          if (key == id) {
            ranges[key]();
          }
        });
      };
      setRange(id, value);
    },
    checkUdcbLimits(id, val) {
      const data = this.getData();
      const over = data.input.faultLimitsData[2].value;
      const max = data.input.hardwareScalesData[1].value;
      const trip = data.input.faultLimitsData[0].value;
      const under = data.input.faultLimitsData[1].value;
      const limits = {
        parametersUdcbMax: (value) => {
          return value > over;
        },
        parametersUdcbOver: (value) => {
          return value < max && value > trip;
        },
        parametersUdcbTrip: (value) => {
          return value < over && value > under;
        },
        parametersUdcbUnder: (value) => {
          return value < trip;
        },
      };
      if (typeof limits[id] !== "undefined") {
        return limits[id](val);
      } else {
        return true;
      }
    },
    /**
     * validates given input, if valid emits it to the main canvas
     * @param {string} id
     * @param {number} displayValue
     * @param {boolean} needsValidation
     * @returns {none}
     */
    sendValue(id, displayValue, needsValidation) {
      // After first interaction with input, displayValue might be a string, so convert to number
      // console.log("CurrLopp 1: id: ", id, typeof id, "dispValue: ", displayValue, "datatype: ", typeof displayValue);
      if(typeof displayValue == 'string'){
        displayValue = Number(displayValue); // Convert string to number
      }
      //console.log("CurrLoop 2: id: ", id, typeof id, "dispValue: ", displayValue, "datatype: ", typeof displayValue);
      
      this.setLimits(id, displayValue);
      getFieldById(id, this.getData(), (field) => {
        const setError = (errorMessage, warningMessage) => {
          this.isWrong = true;
          field.className = "bg-danger";
          this.warningMessage = this.warningMessage.replace(warningMessage, "");
          if (this.warningMessage === "") {
            this.isWarning = false;
          }
          if (!this.errorMessage.includes(errorMessage)) {
            this.errorMessage += errorMessage;
          }
        }
        const setWarning = (warningMessage, errorMessage) => {
          this.isWarning = true;
          field.className = "bg-warning";
          this.errorMessage = this.errorMessage.replace(errorMessage, "");
          if (this.errorMessage === "") {
            this.isWrong = false;
          }
          if (!this.warningMessage.includes(warningMessage)) {
            this.warningMessage += warningMessage;
          }

        }
        const type = field.validation.isFloat ? "float" : "integer";
        var war = `${field.label} is not in range [${field.validation.minRange} - ${field.validation.maxRange}]! `;
        const err = `${field.label} value is not a number of type ${type}! `;
        if (typeof displayValue !== "number" || isNaN(displayValue) || !Number.isInteger(displayValue) && !field.validation.isFloat) {
          setError(err, war);
        } else if (needsValidation && field.validation.minRange > displayValue || displayValue > field.validation.maxRange) {
          setWarning(war, err);
        } else if (!this.checkUdcbLimits(id, displayValue)) {
          war = `${field.label} does not satisfy the sequence: 0 < UDCbus under < UDCbus trip < UDCbus over < UDCbus max! `;
          setWarning(war, err);
        } else {
          this.errorMessage = this.errorMessage.replace(err, "");
          this.warningMessage = this.warningMessage.replace(war, "");
          field.className = "";
          if (this.warningMessage === "") {
            this.isWarning = false;
          }
          if (this.errorMessage === "") {
            this.isWrong = false;
          }
        }
        
        // Store display value as entered by user
        field.value = displayValue;
      });
      
      if (!this.isWrong) {
        // Convert to base value before emitting for calculations
        const baseValue = toBaseValue(id, displayValue);
        this.$emit("value-was-sent", [id, baseValue]);

        // Check if this field has a FreeMASTER mapping and emit update request
        const freeMasterMappings = {
          "parametersPp": "MID: Known Param Pp",
        };
        
        if (freeMasterMappings[id]) {
          this.$emit("freemaster-update-request", {
            varName: freeMasterMappings[id],
            value: baseValue,
            fieldId: id
          });
        }

        this.errorMessage = "";
      }
    },
    /**
     * Initialize units with appropriate prefixes based on scaling configuration
     */
    initializeUnits() {
      try {
        const data = this.getData();
        const allFields = [
          ...data.input.motorParametersData,
          ...data.input.hardwareScalesData,
          ...data.input.faultLimitsData,
          ...data.input.applicationScalesData,
          ...data.input.alignmentData,
        ];

        allFields.forEach(field => {
          if (field && field.type === 'input' && field.id && field.unit) {
            if (!field.originalUnit) {
              field.originalUnit = field.unit;
            }
            field.unit = addPrefixToUnit(field.id, field.originalUnit);
          }
        });
      } catch (error) {
        console.warn('Error initializing units:', error);
      }
    },
  },
  mounted() {
    this.initializeUnits();
  },
  watch: {
    needData: function (newVal) {
      if (newVal) {
        this.$emit("test-data-was-sent", this.getData());
      }
    },
    parametersOutputs: function (newVal) {
      const thisRef = this;
      if (newVal) {
        const id = newVal.id;
        const baseVal = newVal.value;
        getFieldById(id, thisRef.getData(), function (field) {
          if (!isNaN(baseVal) && baseVal !== "") {
            setFieldFromBaseValue(field, baseVal);
            thisRef.setLimits(id, baseVal);
          }
        });
      }
    },
    reloadData: function (newVal) {
      const thisRef = this;
      if (newVal) {
        thisRef.isWrong = false;
        thisRef.errorMessage = "";
        thisRef.setData(newVal.id, newVal.value);
      }
    },
    limits: function (newVal) {
      if (newVal) {
        const id = newVal.id;
        const value = newVal.value;
        const pp = this.getData().input.motorParametersData[0];
        const nMax = this.getData().input.applicationScalesData[0];
        if (id === "currentLoopSampleTime") {
          nMax.validation.sampleTime = value;
          this.setLimits(pp.id, pp.value);
        }
      }
    },
  },
};
</script>