<template>
  <section ref="sensorlessCanvas" v-if="visible">
    <div class="alert alert-warning" v-if="isWarning">
      <strong>Warning! </strong>
      <slot> {{ warningMessage }}</slot>
    </div>
    <div class="alert alert-danger" v-if="isWrong">
      <strong>Error! </strong>
      <slot> {{ errorMessage }}</slot>
    </div>
    <div class="row">
      <div class="col border-end" v-for="column in columns" :key="column.index">
        <div v-for="section in column.sections" :key="section.name">
          <hr />
          <span class="text-uppercase fw-bold">
            {{ section.name }}
          </span>
          <div class="row m-1" v-for="item in section.fields" :key="item.id" :title="item.hint">
            <div class="col-4 d-flex align-items-center justify-content-end">
              <label :for="item.id"> {{ item.label }}: </label>
            </div>
            <div class="col-4">
              <input :class="item.className.field + ' ' + item.className.color" autocomplete="off" :ref="item.id"
                :disabled="item.disabled" v-model.number="item.value" :type="item.type"
                @keyup.enter="$event.target.blur()" @blur="sendValue(item.id, item.value, true)" />
            </div>
            <div class="col-1 d-flex align-items-center justify-content-start">
              <label v-if="item.hasUnit" :for="item.id" v-html="'[' + item.unit + ']'">
              </label>
            </div>
          </div>
          <hr />
        </div>
      </div>
      <hr />
    </div>
  </section>
</template>

<script>
import { getFieldById } from "../logic/utils";
import { toBaseValue, setFieldFromBaseValue, addPrefixToUnit } from "../functions/scalingConfig";
export default {
  name: "SensorlessCanvas",
  props: ["visible", "needData", "sensorlessOutputs", "reloadData", "limits"],
  data() {
    return {
      isWrong: false,
      isWarning: false,
      warningMessage: "",
      errorMessage: "",
      score: [],
      columns: [
        {
          index: "column1",
          sections: [
            {
              name: "Bemf Observer parameters",
              fields: [
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "sensorlessBemfObsrvF0",
                  label: "F0",
                  unit: "Hz",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "BEMF observer bandwidth.",
                  validation: {
                    type: "number",
                    isFloat: false,
                    minRange: 0,
                    maxRange: 2000,
                  },
                },
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "sensorlessBemfObsrvKsi",
                  label: "ξ",
                  unit: "",
                  disabled: false,
                  value: "",
                  hasUnit: false,
                  hint: "BEMF observer attenuation.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 10.0,
                  },
                },
              ],
            },
            {
              name: "Tracking Observer parameters",
              fields: [
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "sensorlessTrackObsrvF0",
                  label: "F0",
                  unit: "Hz",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Tracking observer bandwidth.",
                  validation: {
                    type: "number",
                    isFloat: false,
                    minRange: 0,
                    maxRange: 200,
                  },
                },
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "sensorlessTrackObsrvKsi",
                  label: "ξ",
                  unit: "",
                  disabled: false,
                  value: "",
                  hasUnit: false,
                  hint: "Tracking observer attenuation.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 10.0,
                  },
                },
              ],
            },
            {
              name: "TO IIR speed filter",
              fields: [
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "sensorlessTrackObsrvIIRSpeedCutOff",
                  label: "Cut-off freq",
                  unit: "Hz",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Tracking observer IIR speed filter cut-off frequency.",
                  validation: {
                    type: "number",
                    isFloat: false,
                    minRange: 1,
                    maxRange: 5000,
                  },
                },
              ],
            },
            {
              name: "Open Loop Start-up parameters",
              fields: [
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "sensorlessStartupRamp",
                  label: "Start-up ramp",
                  unit: "rpm/sec",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Open loop startup ramp.",
                  validation: {
                    type: "number",
                    isFloat: false,
                    minRange: 0,
                    maxRange: 50000,
                  },
                },
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "sensorlessStartupCurrent",
                  label: "Start-up current",
                  unit: "A",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Open loop startup current.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0,
                    maxRange: "",
                  },
                },
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "sensorlessMergingSpeed",
                  label: "Merging Speed",
                  unit: "rpm",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Merging speed.",
                  validation: {
                    type: "number",
                    isFloat: false,
                    minRange: "",
                    maxRange: "",
                  },
                },
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "sensorlessMergingCoeff",
                  label: "Merging Coefficient",
                  unit: "%",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Merging coefficient (100% = merging is done within one electrical revolution).",
                  validation: {
                    type: "number",
                    isFloat: false,
                    minRange: 2,
                    maxRange: 1000,
                  },
                },
              ],
            },
          ],
        },
        {
          index: "column2",
          sections: [
            {
              name: "BEMF DQ Observer Constants",
              fields: [
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "sensorlessBemfIScale",
                  label: "I scale",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "BEMF I scale constant",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "sensorlessBemfUScale",
                  label: "U scale",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "BEMF U scale constant",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "sensorlessBemfEScale",
                  label: "E scale",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "BEMF E scale constant",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "sensorlessBemfWIScale",
                  label: "WI scale",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "BEMF WI scale constant",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "sensorlessBemfKp",
                  label: "Bemf Kp",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Proportional gain of BEMF PI controller.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "sensorlessBemfKi",
                  label: "Bemf Ki",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Intergration gain of BEMF PI controller.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },
              ],
            },
            {
              name: "Tracking Observer Constants",
              fields: [
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "sensorlessToKp",
                  label: "TO Kp",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Proportional gain of TO PI controller.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "sensorlessToKi",
                  label: "TO Ki",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Integration gain of TO PI controller.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "sensorlessThetaK",
                  label: "Theta K",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Theta_K TO constant",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "sensorlessToIirB0",
                  label: "IIR B0",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Calculated TO IIR B0 constant.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "sensorlessToIirB1",
                  label: "IIR B1",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Calculated TO IIR B1 constant.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "sensorlessToIirA1",
                  label: "IIR A1",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Calculated TO IIR A1 constant.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },
              ],
            },
          ],
        },
      ],
    };
  },
  methods: {
    /**
     * simplifies grid structure for data manipulation. If new *section* is added / deleted it has to be manually changed
     * @param {none}
     * @returns {object} grid data divided into input / output group
     */
    getData() {
      const inputData = this.columns[0].sections;
      const outputData = this.columns[1].sections;
      const bemfObsrv = inputData[0].fields;
      const trackObsrv = inputData[1].fields;
      const trackObsrvIIRSpeed = inputData[2].fields;
      const openloopStartup = inputData[3].fields;
      const bemfObserverConstants = outputData[0].fields;
      const trackObserverConstants = outputData[1].fields;
      return {
        input: {
          bemfObsrv,
          trackObsrv,
          trackObsrvIIRSpeed,
          openloopStartup,
        },
        output: {
          bemfObserverConstants,
          trackObserverConstants,
        },
      };
    },
    /**
     * sets a value to a specific field given an id
     * @param {string} id
     * @param {number} baseValue
     * @returns {none}
     */
    setData(id, baseValue) {
      getFieldById(id, this.getData(), (field) => {
        setFieldFromBaseValue(field, baseValue);
      });
    },
    /**
     * validates given input, if valid emits it to the main canvas
     * @param {string} id
     * @param {number} displayValue
     * @param {boolean} needsValidation
     * @returns {none}
     */
    sendValue(id, displayValue, needsValidation) {
      // After first interaction with input, displayValue might be a string, so convert to number
      // console.log("CurrLopp 1: id: ", id, typeof id, "dispValue: ", displayValue, "datatype: ", typeof displayValue);
      if(typeof displayValue == 'string'){
        displayValue = Number(displayValue); // Convert string to number
      }
      //console.log("CurrLoop 2: id: ", id, typeof id, "dispValue: ", displayValue, "datatype: ", typeof displayValue);

      getFieldById(id, this.getData(), (field) => {
        const setError = () => {
          this.isWrong = true;
          field.className.color = "bg-danger";
          this.warningMessage = this.warningMessage.replace(war, "");
          if (this.warningMessage === "") {
            this.isWarning = false;
          }
          if (!this.errorMessage.includes(err)) {
            this.errorMessage += err;
          }
        };
        const setWarning = () => {
          this.isWarning = true;
          field.className.color = "bg-warning";
          this.errorMessage = this.errorMessage.replace(err, "");
          if (this.errorMessage === "") {
            this.isWrong = false;
          }
          if (!this.warningMessage.includes(war)) {
            this.warningMessage += war;
          }
        };
        const type = field.validation.isFloat ? "float" : "integer";
        const war = `${field.label} is not in range [${field.validation.minRange} - ${field.validation.maxRange}]! `;
        const err = `${field.label} value is not a number of type ${type}! `;
        if (
          typeof displayValue !== "number" ||
          isNaN(displayValue) ||
          (!Number.isInteger(displayValue) && !field.validation.isFloat)
        ) {
          setError();
        } else if (
          (needsValidation && field.validation.minRange > displayValue) ||
          displayValue > field.validation.maxRange
        ) {
          setWarning();
        } else {
          this.errorMessage = this.errorMessage.replace(err, "");
          this.warningMessage = this.warningMessage.replace(war, "");
          field.className.color = "";
          if (this.warningMessage === "") {
            this.isWarning = false;
          }
          if (this.errorMessage === "") {
            this.isWrong = false;
          }
        }
        
        field.value = displayValue;
      });
      
      if (!this.isWrong) {
        const baseValue = toBaseValue(id, displayValue);
        this.$emit("value-was-sent", [id, baseValue]);
        this.errorMessage = "";
      }
    },
    initializeUnits() {
      try {
        const allFields = [
          ...this.getData().input.bemfObsrv,
          ...this.getData().input.trackObsrv,
          ...this.getData().input.trackObsrvIIRSpeed,
          ...this.getData().input.openloopStartup,
          ...this.getData().output.bemfObserverConstants,
          ...this.getData().output.trackObserverConstants,
        ];

        allFields.forEach(field => {
          if (field && field.type === 'input' && field.id && field.unit) {
            if (!field.originalUnit) {
              field.originalUnit = field.unit;
            }
            field.unit = addPrefixToUnit(field.id, field.originalUnit);
          }
        });
      } catch (error) {
        console.warn('Error initializing units:', error);
      }
    },
  },
  mounted() {
    this.initializeUnits();
  },
  watch: {
    sensorlessOutputs: function (newVal) {
      const thisRef = this;
      if (newVal) {
        const id = newVal.id;
        const baseVal = newVal.value;
        const outputs = [
          "sensorlessBemfIScale",
          "sensorlessBemfUScale",
          "sensorlessBemfEScale",
          "sensorlessBemfWIScale",
          "sensorlessBemfKp",
          "sensorlessBemfKi",
          "sensorlessToKp",
          "sensorlessToKi",
          "sensorlessThetaK",
          "sensorlessToIirB0",
          "sensorlessToIirB1",
          "sensorlessToIirA1",
        ];
        getFieldById(id, thisRef.getData(), function (field) {
          if (outputs.includes(id) && !isNaN(baseVal) && baseVal !== "") {
            setFieldFromBaseValue(field, baseVal);
          }
        });
      }
    },
    needData: function (newVal) {
      if (newVal) {
        this.$emit("test-data-was-sent", this.getData());
      }
    },
    reloadData: function (newVal) {
      const thisRef = this;
      if (newVal) {
        thisRef.isWrong = false;
        thisRef.errorMessage = "";
        thisRef.setData(newVal.id, newVal.value);
      }
    },
    limits: function (newVal) {
      if (newVal) {
        const id = newVal.id;
        const value = newVal.value;
        const startUpCurrent = this.getData().input.openloopStartup[1];
        const mergingSpeed = this.getData().input.openloopStartup[2];
        const setLimit = {
          parametersImax: () => {
            startUpCurrent.validation.maxRange = value;
          },
          parametersNmin: () => {
            mergingSpeed.validation.minRange = value;
          },
          parametersNover: () => {
            mergingSpeed.validation.maxRange = value;
          },
        };
        if (typeof setLimit[id] !== "undefined") {
          setLimit[id]();
        }
      }
    },
  },
};
</script>