import { join } from "path";
import { HeaderFile } from "./model/file";
import { extractComments, extractDataFromFile, validateOutputFile } from "./outputFile"

export class Setup {
    defaultFile = "m1_pmsm_appconfig.h";

    constructor(ref) {
        this.ref = ref;
        this.pcm = ref.pcmStructure;
        this.pcm.startPcm();
    }

    getData() {
        return {
            mid: this.ref.mid,
            parameters: this.ref.parameters,
            speedLoop: this.ref.speedLoop,
            positionLoop: this.ref.positionLoop,
            currentLoop: this.ref.currentLoop,
            sensorless: this.ref.sensorless
        }
    }

    getBoardId(callback) {
        this.pcm.readVariable("Board ID", (data) => {
            if (data !== "" && typeof data !== "undefined") {
                callback(data.formatted);
            }
        });
    }

    setBoardId(id) {
        if (id !== "" && typeof id !== "undefined") {
            this.ref.boardInfo.boardId = "Board found: " + id.toUpperCase();
            this.ref.boardInfo.class = "alert-primary";
            this.ref.boardInfo.errorMessage = "";
        } else {
            this.ref.boardInfo.class = "alert-danger";
            this.ref.boardInfo.boardId = "";
            this.ref.boardInfo.errorMessage = "Board ID not found - check freeMaster connection!";
        }

    }

    buildInputPaths(boardId, exampleId, userPath1, userPath2) {
            return [
                join(
                    userPath1,
                    this.defaultFile
                ),
                join(
                    userPath2,
                    this.defaultFile
                ),
                join(
                    "..",
                    "boards",
                    boardId,
                    "mc_pmsm",
                    exampleId,
                    this.defaultFile
                ),
                join(
                    "..",
                    "..",
                    "..",
                    "boards",
                    boardId,
                    "demo_apps",
                    "mc_pmsm",
                    exampleId,
                    this.defaultFile
                ),
                join(
                    "..",
                    "..",
                    "..",
                    "boards",
                    boardId,
                    "demo_apps",
                    "mc_pmsm",
                    exampleId,
                    "cm7",
                    this.defaultFile
                ),
                join(
                    "..",
                    "..",
                    "..",
                    "boards",
                    boardId,
                    "demo_apps",
                    "mc_pmsm",
                    exampleId,
                    "cm33_core0",
                    this.defaultFile
                ),
                join("..", "..", "source", this.defaultFile),
                this.defaultFile,
            ];
    }

    getInputPath(pathsList, attempts) {
        return new Promise((resolve, reject) => {
            pathsList.forEach((path) => {
                this.pcm
                    .checkIfFileExists(path)
                    .then((response) => {
                        return resolve(response);
                    })
                    .catch(() => {
                        attempts += 1;
                        if (attempts === pathsList.length) {
                            return reject("Tried all, no m1_pmsm_appconfig file fits.");
                        }
                    });
            });
        });
    }

    createHeaderFile(path, name, callback) {
        this.pcm.checkIfFileExists(path).then(() => {
            this.pcm.readOutputFileContents(path, (data) => {
                const comments = extractComments(data);
                const commentsData = extractDataFromFile(comments, data);
                const isValid = validateOutputFile(this.getData(), commentsData);
                if (isValid) {
                    const headerFile = new HeaderFile(path, name);
                    headerFile.copyright = commentsData.copyright;
                    const motor = JSON.parse(commentsData.motorIdentification);
                    headerFile.motorId = motor.motorName;
                    headerFile.description = motor.motorDescription;
                    headerFile.userInput = commentsData.userInput;
                    headerFile.values = JSON.parse(commentsData.parsedData, function (key, value) {
                        return (typeof value === "string" || isNaN(value)) || typeof (value) === "boolean" ? value : parseFloat(value);
                    });
                    callback(headerFile);
                } else {
                    callback(undefined);
                }

            });
        }).catch(() => {
            callback(undefined);
        })

    }
}