<template>
  <section ref="PositionLoopCanvas" v-if="visible">
    <div class="alert alert-warning" v-if="isWarning">
      <strong>Warning! </strong>
      <slot> {{ warningMessage }}</slot>
    </div>
    <div class="alert alert-danger" v-if="isWrong">
      <strong>Error! </strong>
      <slot> {{ errorMessage }}</slot>
    </div>
    <div class="row">
      <div class="col border-end" v-for="column in columns" :key="column.index">
        <div v-for="section in column.sections" :key="section.name">
          <hr />
          <span class="text-uppercase fw-bold">
            {{ section.name }}
          </span>
          <div class="row m-1" v-for="item in section.fields" :key="item.id" :title="item.hint">
            <div class="col-4 d-flex align-items-center justify-content-end">
              <label :for="item.id"> {{ item.label }}: </label>
            </div>
            <div class="col-4">
              <input :class="item.className.field + ' ' + item.className.color" autocomplete="off" :ref="item.id"
                :disabled="item.disabled" v-model.number="item.value" :type="item.type"
                @keyup.enter="$event.target.blur()" @blur="sendValue(item.id, item.value, true)" />
            </div>
            <div class="col-1 d-flex align-items-center justify-content-start">
              <label v-if="item.hasUnit" :for="item.id" v-html="'[' + item.unit + ']'">
              </label>
            </div>
          </div>
          <hr />
        </div>
      </div>
      <hr />
    </div>
  </section>
</template>
 
<script>
import { getFieldById } from "../logic/utils";
import { toBaseValue, setFieldFromBaseValue, addPrefixToUnit } from "../functions/scalingConfig";
export default {
  name: "PositionLoopCanvas",
  props: ["visible", "needData", "positionLoopOutputs", "reloadData"],
  data() {
    return {
      isWrong: false,
      isWarning: false,
      errorMessage: "",
      warningMessage: "",
      columns: [
        {
          index: "column1",
          sections: [
          {
              name: "Servo control parameters",
              fields: [

                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "positionLoopSampleTime",
                  label: "Sample time Ts",
                  unit: "sec",
                  disabled: true,
                  value: "",
                  hasUnit: true,
                  hint: "Slow control loop period.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.00001,
                    maxRange: 0.1,
                  },
                },

                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "positionLoopF0",
                  label: "Bandwidth F0",
                  unit: "Hz",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Position controllers' bandwidth.",
                  validation: {
                    type: "number",
                    isFloat: false,
                    minRange: 0,
                    maxRange: 500,
                  },
                },

                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "positionLoopKsi",
                  label: "Attenuation ξ",
                  unit: "",
                  disabled: false,
                  value: "",
                  hasUnit: false,
                  hint: "Position controllers' attenuation.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 10.0,
                  },
                },

              ],
            },
            {
              name: "Position loop - P controller limits",
              fields: [

                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "servo_positionLoopUpperLimit",
                  label: "Upper limit",
                  unit: "rpm",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Maximal required speed (position controller's output).",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0,
                    maxRange: 5000,
                  },
                },

                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "servo_positionLoopLowerLimit",
                  label: "Lower limit",
                  unit: "rpm",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Minimal required speed (position controller's output).",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: -5000,
                    maxRange: 0,
                  },
                },

              ],
            },


            {
              name: "Speed loop - PI controller limits",
              fields: [

                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "servo_speedLoopUpperLimit",
                  label: "Upper limit",
                  unit: "A",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Maximal required Q-axis current (speed controller's output).",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0,
                    maxRange: 100,
                  },
                },

                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "servo_speedLoopLowerLimit",
                  label: "Lower limit",
                  unit: "A",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Minimal required Q-axis current (speed controller's output).",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: -100,
                    maxRange: 0,
                  },
                },

              ],
            },


          ],
        },
        {
          index: "column2",
          sections: [
            {
              name: "Position loop - P controller gain",
              fields: [
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "servo_positionLoopKp",
                  label: "Proportional gain",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Proportional gain of Position controller. (in Z-domain)",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },

              ],
            },

            {
              name: "Position loop - Feedforward coeficients",
              fields: [
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "servo_positionFeedFrwdK1",
                  label: "K1 coefficient",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Feedforward K1 coefficient.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "servo_positionFeedFrwdK2",
                  label: "K2 coefficient",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Feedforward K2 coefficient.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },

              ],
            },

            {
              name: "speed loop - zero cancellation filter",
              fields: [
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "servo_speedLoopIIRB0_ZC",
                  label: "B0",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Calculated Speed IIR zero cancellation filter B0 constant  (for servo control).",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "servo_speedLoopIIRB1_ZC",
                  label: "B1",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Calculated Speed IIR zero cancellation filter B1 constant  (for servo control).",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "servo_speedLoopIIRA1_ZC",
                  label: "A1",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Calculated Speed IIR zero cancellation filter (-1)*A1 constant  (for servo control).",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },
              ],
            },

            {
              name: "speed loop - Speed PI controller gains",
              fields: [
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "servo_speedLoopKp",
                  label: "Proportional gain",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Proportional gain of Speed PI controller (In Z-domain).",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },

                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "servo_speedLoopKi",
                  label: "Integration gain",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Integration gain of Speed PI controller (In Z-domain).",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },

              ],
            },

          ],
        },
      ],
    };
  },
  methods: {
    /**
     * simplifies grid structure for data manipulation. If new *section* is added / deleted it has to be manually changed
     * @param {none}
     * @returns {object} grid data divided into input / output group
     */
     getData() {
      const inputData = this.columns[0].sections;
      const outputData = this.columns[1].sections;

      const ServoParameters = inputData[0].fields;
      const servo_positionPControllerLimits = inputData[1].fields;
      const servo_speedPIControllerLimits = inputData[2].fields;
      
      const servo_positionPControllerConstants = outputData[0].fields;
      const servo_positionFeedFRWDConstants = outputData[1].fields;
      const servo_speedZCFilterConstants =  outputData[2].fields;
      const servo_speedPIControllerConstants = outputData[3].fields;

      return {
        input: {
          ServoParameters,
          servo_positionPControllerLimits,
          servo_speedPIControllerLimits,
        },
        output: {
          servo_positionPControllerConstants,
          servo_positionFeedFRWDConstants,
          servo_speedZCFilterConstants,
          servo_speedPIControllerConstants,
        },
      };
    },
    /**
     * sets a value to a specific field given an id
     * @param {string} id
     * @param {number} baseValue
     * @returns {none}
     */
    setData(id, baseValue) {
      getFieldById(id, this.getData(), (field) => {
        setFieldFromBaseValue(field, baseValue);
      });
    },
    /**
     * validates given input, if valid emits it to the main canvas
     * @param {string} id
     * @param {number} displayValue
     * @param {boolean} needsValidation
     * @returns {none}
     */
    sendValue(id, displayValue, needsValidation) {
      // After first interaction with input, displayValue might be a string, so convert to number
      // console.log("CurrLopp 1: id: ", id, typeof id, "dispValue: ", displayValue, "datatype: ", typeof displayValue);
      if(typeof displayValue == 'string'){
        displayValue = Number(displayValue); // Convert string to number
      }
      //console.log("CurrLoop 2: id: ", id, typeof id, "dispValue: ", displayValue, "datatype: ", typeof displayValue);

      getFieldById(id, this.getData(), (field) => {
        const setError = () => {
          this.isWrong = true;
          field.className.color = "bg-danger";
          this.warningMessage = this.warningMessage.replace(war, "");
          if (this.warningMessage === "") {
            this.isWarning = false;
          }
          if (!this.errorMessage.includes(err)) {
            this.errorMessage += err;
          }
        };
        const setWarning = () => {
          this.isWarning = true;
          field.className.color = "bg-warning";
          this.errorMessage = this.errorMessage.replace(err, "");
          if (this.errorMessage === "") {
            this.isWrong = false;
          }
          if (!this.warningMessage.includes(war)) {
            this.warningMessage += war;
          }
        };
        const type = field.validation.isFloat ? "float" : "integer";
        var war = `${field.label} is not in range [${field.validation.minRange} - ${field.validation.maxRange}]! `;
        const err = `${field.label} value is not a number of type ${type}! `;
        if (typeof displayValue !== "number" || isNaN(displayValue) || !Number.isInteger(displayValue) && !field.validation.isFloat) {
          setError();
        } else if (needsValidation && field.validation.minRange > displayValue || displayValue > field.validation.maxRange) {
          setWarning();
        } else {
          this.errorMessage = this.errorMessage.replace(err, "");
          this.warningMessage = this.warningMessage.replace(war, "");
          field.className.color = "";
          if (this.warningMessage === "") {
            this.isWarning = false;
          }
          if (this.errorMessage === "") {
            this.isWrong = false;
          }
        }
        
        field.value = displayValue;
      });
      
      if (!this.isWrong) {
        const baseValue = toBaseValue(id, displayValue);
        this.$emit("value-was-sent", [id, baseValue]);
        this.errorMessage = "";
      }
    },
    initializeUnits() {
      try {
        const allFields = [
          ...this.getData().input.ServoParameters,
          ...this.getData().input.servo_positionPControllerLimits,
          ...this.getData().input.servo_speedPIControllerLimits,
          ...this.getData().output.servo_positionPControllerConstants,
          ...this.getData().output.servo_positionFeedFRWDConstants,
          ...this.getData().output.servo_speedZCFilterConstants,
          ...this.getData().output.servo_speedPIControllerConstants,
        ];

        allFields.forEach(field => {
          if (field && field.type === 'input' && field.id && field.unit) {
            if (!field.originalUnit) {
              field.originalUnit = field.unit;
            }
            field.unit = addPrefixToUnit(field.id, field.originalUnit);
          }
        });
      } catch (error) {
        console.warn('Error initializing units:', error);
      }
    },
  },
  mounted() {
    this.initializeUnits();
  },
  watch: {
    positionLoopOutputs: function (newVal) {
      const thisRef = this;
      if (newVal) {
        const id = newVal.id;
        const baseVal = newVal.value;
        const outputs = [
          "servo_positionLoopKp",
          "servo_positionFeedFrwdK1",
          "servo_positionFeedFrwdK2",
          "servo_speedLoopIIRB0_ZC",
          "servo_speedLoopIIRB1_ZC",
          "servo_speedLoopIIRA1_ZC",
          "servo_speedLoopKp",
          "servo_speedLoopKi",
        ];
        getFieldById(id, thisRef.getData(), function (field) {
          if (outputs.includes(id) && !isNaN(baseVal) && baseVal !== "") {
            setFieldFromBaseValue(field, baseVal);
          }
        });
      }
    },
    needData: function (newVal) {
      if (newVal) {
        this.$emit("test-data-was-sent", this.getData());
      }
    },
    reloadData: function (newVal) {
      const thisRef = this;
      if (newVal) {
        thisRef.isWrong = false;
        thisRef.errorMessage = "";
        thisRef.setData(newVal.id, newVal.value);
      }
    },
  },
};
</script>