<template>
  <section ref="gridDesign" v-if="visible">
    <div class="row">
      <div class="col border-right" v-for="column in grid" :key="column.index">
        <div v-for="section in column.sections" :key="section.name">
          <span class="text-uppercase font-weight-bold">
            {{ section.name }}
          </span>
          <div class="row" v-for="item in section.fields" :key="item.id">
            <div class="col">
              <label :for="item.id"> {{ item.label }}: </label>
            </div>
            <div class="col">
              <input
                class="form-control"
                autocomplete="off"
                :ref="item.id"
                :disabled="item.disabled"
                v-model.number="item.value"
                :type="item.type"
                @blur="sendValue(item.id, item.value)"
              />
            </div>
            <div class="col">
              <label :for="item.id"> [{{ item.unit }}] </label>
            </div>
          </div>
          <hr />
        </div>
      </div>
      <hr />
    </div>
  </section>
</template>

