<template>
  <section id="developerMode" v-if="visible">
    <div class="row">
      <div class="col">
        <div class="row" v-if="!testingInProgress">
          <div class="col">
            <div class="row">
              <label>WELCOME TO M_CAT DEVELOPER MODE</label>
            </div>
          </div>
        </div>
        <div class="row">
          <div class="col">
            <button
              class="btn btn-primary btn-block btn-group-lg"
              ref="testButton"
              @click="testGrid()"
              :disabled="testingInProgress"
            >
              {{ buttonText }}
            </button>
          </div>
          <div class="col" v-show="testingFinished">
            <button
              class="btn btn-info btn-block btn-group-lg"
              ref="clearButton"
              @click="clear()"
            >
              {{ clearText }}
            </button>
          </div>
        </div>
        <div class="row d-block" v-html="contents" />
      </div>
    </div>
  </section>
</template>

<script>
export default {
  name: "DeveloperModeCanvas",
  props: [
    "visible",
    "mainCanvasData",
    "midData",
    "currentLoopData",
    "speedLoopData",
    "sensorlessData",
    "positionLoopData",
    "parametersData",
    "newCanvasData",
  ],
  data() {
    return {
      testingInProgress: false,
      testingFinished: false,
      devData: {
        mainCanvas: "",
        mid: "",
        currentLoop: "",
        speedLoop: "",
        sensorless: "",
        positionLoop: "",
        parameters: "",
        newCanvas: "",
      },
      buttonText: "START TESTING",
      clearText: "CLEAR RESULT",
      buttonTextToggle: {
        start: "START TESTING",
        progress: "TESTING IN PROGRESS...",
        end: "TESTING FINISHED",
      },
      contents: "",
    };
  },
  methods: {
    compare(mainCanvas, canvas, name) {
      var c =
        '<hr><mark class="header">==== ' +
        name.toUpperCase() +
        " ====</mark> </br></br>";
      var main = (function () {
        Object.keys(mainCanvas).forEach(function (mainKey) {
          if (mainKey.toUpperCase() == name.replace(" ", "").toUpperCase()) {
            main = mainCanvas[mainKey];
          }
        });
        return main;
      })();
      if (typeof main != typeof String) {
        Object.keys(canvas).forEach(function (io) {
          Object.keys(canvas[io]).forEach(function (section) {
            var sectionFound = false;
            Object.keys(main).forEach(function (mainKey) {
              if (section.startsWith(mainKey)) {
                sectionFound = true;
                c +=
                  "Section <strong>" +
                  section +
                  '</strong> was <mark class="green">found</mark> in main data.</br>';
                Object.keys(canvas[io][section]).forEach(function (y) {
                  var fieldFound = false;
                  Object.keys(main[mainKey]).forEach(function (x) {
                    if (x == canvas[io][section][y].id) {
                      fieldFound = true;
                      c +=
                        "Field <i>" +
                        x +
                        '</i> was <mark class="green">found</mark> in main data.</br>';
                    }
                  });
                    if (!fieldFound) {
                    c +=
                      "Field </i>" +
                      canvas[io][section][y].id +
                      '</i> was <mark class="red">not found</mark> in main data.</br>';
                  }
                });
              }
            });
            c += "</br>";
            if (!sectionFound) {
              c +=
                "Section: " +
                section +
                ' was <mark class="red">not found</mark> in main data</br>';
            }
          });
        });
      } else {
        c +=
          "Canvas: <b><u>" +
          name +
          '</u></b> was <mark class="red">not found</mark> in main data</br>';
      }
      this.contents += c + "<hr>";
    },
    testGrid() {
      if (!this.testingInProgress && !this.contents) {
        this.testingInProgress = true;
        this.testingFinished = false;
        this.buttonText = this.buttonTextToggle.progress;
        Object.keys(this.devData)
          .filter((key) => !key.includes("mainCanvas"))
          .forEach((key) =>
            this.compare(this.devData.mainCanvas, this.devData[key], key)          
          );
        setTimeout(() => {
          this.testingInProgress = false;
          this.testingFinished = true;
        }, 3000);
      }
    },
    clear() {
      this.contents = "";
      this.testingInProgress = false;
      setTimeout(() => {
        this.testingFinished = false;
      }, 1000);
    },
  },
  watch: {
    visible: function (newVal) {
      if (newVal) {
        this.$emit("testing-started");
      }
    },
    midData: function (newVal) {
      if (newVal) {
        this.devData.mid = newVal;
      }
    },
    parametersData: function (newVal) {
      if (newVal) {
        this.devData.parameters = newVal;
      }
    },
    currentLoopData: function (newVal) {
      if (newVal) {
        this.devData.currentLoop = newVal;
      }
    },
    speedLoopData: function (newVal) {
      if (newVal) {
        this.devData.speedLoop = newVal;
      }
    },
    positionLoopData: function (newVal) {
      if (newVal) {
        this.devData.positionLoop = newVal;
      }
    },
    sensorlessData: function (newVal) {
      if (newVal) {
        this.devData.sensorless = newVal;
      }
    },
    newCanvasData: function (newVal) {
      if (newVal) {
        this.devData.newCanvas = newVal;
      }
    },
    mainCanvasData: function (newVal) {
      if (newVal) {
        this.devData.mainCanvas = newVal;
      }
    },
    testingInProgress: function (newVal, oldVal) {
      if (newVal && !oldVal) {
        this.buttonText = this.buttonTextToggle.start;
      } else if (!newVal && oldVal) {
        this.buttonText = this.buttonTextToggle.end;
      }
    },
    testingFinished: function (newVal) {
      if (!newVal) {
        this.buttonText = this.buttonTextToggle.start;
      }
    },
  },
};
</script>