<template>
  <section ref="currentLoopCanvas" v-if="visible">
    <div class="alert alert-warning" v-if="isWarning">
      <strong>Warning! </strong>
      <slot> {{ warningMessage }}</slot>
    </div>
    <div class="alert alert-danger" v-if="isWrong">
      <strong>Error! </strong>
      <slot> {{ errorMessage }}</slot>
    </div>
    <div class="row">
      <div class="col border-end" v-for="column in columns" :key="column.index">
        <div v-for="section in column.sections" :key="section.name">
          <hr />
          <span class="text-uppercase fw-bold">
            {{ section.name }}
          </span>
          <div class="row" v-for="item in section.fields" :key="item.id" :title="item.hint">
            <div class="col-4 d-flex align-items-center justify-content-end">
              <label :for="item.id"> {{ item.label }}: </label>
            </div>
            <div class="col-4 m-1">
              <input :class="'form-control ' + item.className" autocomplete="off" :ref="item.id"
                :disabled="item.disabled" v-model.number="item.value" :type="item.type"
                @keyup.enter="$event.target.blur()" @blur="sendValue(item.id, item.value, true)" />
            </div>
            <div class="col-1 d-flex align-items-center justify-content-start">
              <label v-if="item.hasUnit" :for="item.id" v-html="'[' + item.unit + ']'">
              </label>
            </div>
          </div>
          <hr />
        </div>
      </div>
      <hr />
    </div>
  </section>
</template>

<script>
import { getFieldById } from "../logic/utils";
import { toBaseValue, setFieldFromBaseValue, addPrefixToUnit } from "../functions/scalingConfig";
export default {
  name: "CurrentLoopCanvas",
  props: ["visible", "needData", "currentLoopOutputs", "reloadData", "limits"],
  data() {
    return {
      isWrong: false,
      isWarning: false,
      errorMessage: "",
      warningMessage: "",
      columns: [
        {
          index: "column1",
          sections: [
            {
              name: "Loop parameters",
              fields: [
                {
                  type: "input",
                  id: "currentLoopSampleTime",
                  className: "",
                  label: "Sample time",
                  unit: "sec",
                  disabled: true,
                  value: "",
                  hasUnit: true,
                  hint: "Fast control loop period.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.00001,
                    maxRange: 0.001,
                  },
                },
                {
                  type: "input",
                  id: "currentLoopF0",
                  className: "",
                  label: "F0",
                  unit: "Hz",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Current controllers' bandwidth.",
                  validation: {
                    type: "number",
                    isFloat: false,
                    minRange: 10,
                    maxRange: 2000,
                  },
                },
                {
                  type: "input",
                  id: "currentLoopKsi",
                  className: "",
                  label: "ξ",
                  unit: "",
                  disabled: false,
                  value: "",
                  hasUnit: false,
                  hint: "Current controllers' attenuation.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.1,
                    maxRange: 10,
                  },
                },
              ],
            },
            {
              name: "Current PI controller limits",
              fields: [
                {
                  type: "input",
                  id: "currentLoopOutputLimit",
                  label: "Output limit",
                  className: "",
                  unit: "%",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Duty cycle limit.",
                  validation: {
                    type: "number",
                    isFloat: false,
                    minRange: 0,
                    maxRange: 99,
                  },
                },
              ],
            },
          ],
        },
        {
          index: "column2",
          sections: [
            {
              name: "D-axis PI controller constants",
              fields: [
                {
                  type: "input",
                  id: "currentLoopDKp",
                  className: "",
                  label: "D_Kp",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Calculated proportional gain of D-axis current controller (in Z-domain).",
                },
                {
                  type: "input",
                  id: "currentLoopDKi",
                  className: "",
                  label: "D_Ki",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Calculated integration gain of D-axis current controller (in Z-domain).",
                },
              ],
            },
          ],
        },
        {
          index: "column3",
          sections: [
            {
              name: "Q-axis PI controller constants",
              fields: [
                {
                  type: "input",
                  id: "currentLoopQKp",
                  className: "",
                  label: "Q_Kp",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Calculated proportional gain of Q-axis current controller (in Z-domain).",
                },
                {
                  type: "input",
                  id: "currentLoopQKi",
                  className: "",
                  label: "Q_Ki",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Calculated integration gain of Q-axis current controller (in Z-domain).",
                },
              ],
            },
            {
              name: "Q-axis Zero cancellation filter constants",
              fields: [
                {
                  type: "input",
                  id: "currentLoopQZCB0",
                  className: "",
                  label: "B0",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Calculated Current IIR zero cancellation filter B0 constant.",
                },
                {
                  type: "input",
                  id: "currentLoopQZCB1",
                  className: "",
                  label: "B1",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Calculated Current IIR zero cancellation filter B1 constant.",
                },
                                {
                  type: "input",
                  id: "currentLoopQZCA1",
                  className: "",
                  label: "A1",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Calculated Current IIR zero cancellation filter (-1)*A1 constant.",
                },
              ],
            },
          ],
        },
      ],
    };
  },
  methods: {
    /**
     * simplifies grid structure for data manipulation. If new *section* is added / deleted it has to be manually changed
     * @param {none}
     * @returns {object} grid data divided into input / output group
     */
    getData() {
      const inputData = this.columns[0].sections;
      const loopParametersData = inputData[0].fields;
      const currentPIControllerLimitsData = inputData[1].fields;
      const dAxisControllerLimitsData = this.columns[1].sections[0].fields;
      const qAxisControllerLimitsData = this.columns[2].sections[0].fields;
      const qAxisZCfilterData = this.columns[2].sections[1].fields;
      return {
        input: {
          loopParametersData,
          currentPIControllerLimitsData,
        },
        output: {
          dAxisControllerLimitsData,
          qAxisControllerLimitsData,
          qAxisZCfilterData,
        },
      };
    },
    /**
     * sets a value to a specific field given an id
     * @param {string} id
     * @param {number} baseValue
     * @returns {none}
     */
    setData(id, baseValue) {
      getFieldById(id, this.getData(), (field) => {
        setFieldFromBaseValue(field, baseValue);
      });
    },
    sendValue(id, displayValue, needsValidation) {
      // After first interaction with input, displayValue might be a string, so convert to number
      // console.log("CurrLopp 1: id: ", id, typeof id, "dispValue: ", displayValue, "datatype: ", typeof displayValue);
      if(typeof displayValue == 'string'){
        displayValue = Number(displayValue); // Convert string to number
      }
      //console.log("CurrLoop 2: id: ", id, typeof id, "dispValue: ", displayValue, "datatype: ", typeof displayValue);
      
      getFieldById(id, this.getData(), (field) => {
        const setError = () => {
          this.isWrong = true;
          field.className = "bg-danger";
          this.warningMessage = this.warningMessage.replace(war, "");
          if (this.warningMessage === "") {
            this.isWarning = false;
          }
          if (!this.errorMessage.includes(err)) {
            this.errorMessage += err;
          }
        };
        const setWarning = () => {
          this.isWarning = true;
          field.className = "bg-warning";
          this.errorMessage = this.errorMessage.replace(err, "");
          if (this.errorMessage === "") {
            this.isWrong = false;
          }
          if (!this.warningMessage.includes(war)) {
            this.warningMessage += war;
          }
        };
        const type = field.validation.isFloat ? "float" : "integer";
        var war = `${field.label} is not in range [${field.validation.minRange} - ${field.validation.maxRange}]! `;
        const err = `${field.label} value is not a number of type ${type}! `;
        if (typeof displayValue !== "number" || isNaN(displayValue) || !Number.isInteger(displayValue) && !field.validation.isFloat) {
          setError();
        } else if (needsValidation && field.validation.minRange > displayValue || displayValue > field.validation.maxRange) {
          setWarning();
        } else {
          this.errorMessage = this.errorMessage.replace(err, "");
          this.warningMessage = this.warningMessage.replace(war, "");
          field.className = "";
          if (this.warningMessage === "") {
            this.isWarning = false;
          }
          if (this.errorMessage === "") {
            this.isWrong = false;
          }
        }
        
        field.value = displayValue;
      });
      
      if (!this.isWrong) {
        const baseValue = toBaseValue(id, displayValue);
        this.$emit("value-was-sent", [id, baseValue]);
        this.errorMessage = "";
      }
    },
    initializeUnits() {
      try {
        const allFields = [
          ...this.getData().input.loopParametersData,
          ...this.getData().input.currentPIControllerLimitsData,
          ...this.getData().output.dAxisControllerLimitsData,
          ...this.getData().output.qAxisControllerLimitsData,
          ...this.getData().output.qAxisZCfilterData,
        ];

        allFields.forEach(field => {
          if (field && field.type === 'input' && field.id && field.unit) {
            if (!field.originalUnit) {
              field.originalUnit = field.unit;
            }
            field.unit = addPrefixToUnit(field.id, field.originalUnit);
          }
        });
      } catch (error) {
        console.warn('Error initializing units:', error);
      }
    },
  },
  mounted() {
    this.initializeUnits();
  },
  watch: {
    currentLoopOutputs: function (newVal) {
      const thisRef = this;
      if (newVal) {
        const id = newVal.id;
        const baseVal = newVal.value;
        const outputs = [
          "currentLoopDKp",
          "currentLoopDKi",
          "currentLoopQKp", 
          "currentLoopQKi",
          "currentLoopQZCB0",
          "currentLoopQZCB1",
          "currentLoopQZCA1"
        ];
        getFieldById(id, thisRef.getData(), function (field) {
          if (outputs.includes(id) && !isNaN(baseVal) && baseVal !== "") {
            setFieldFromBaseValue(field, baseVal);
          }
        });
      }
    },
    needData: function (newVal) {
      if (newVal) {
        this.$emit("test-data-was-sent", this.getData());
      }
    },
    reloadData: function (newVal) {
      const thisRef = this;
      if (newVal) {
        thisRef.isWrong = false;
        thisRef.errorMessage = "";
        thisRef.setData(newVal.id, newVal.value);
      }
    },
  },
};
</script>