var midFunctions = require("./mid");
var parametersFunctions = require("./parameters");
var currentLoopFunctions = require("./currentLoop");
var speedLoopFunctions = require("./speedLoop");
var positionLoopFunctions = require("./positionLoop");
var sensorlessFunctions = require("./sensorless");

export function calculate(inputStructure) {
    return {
        mid: midFunctions.calculateParams(inputStructure),
        parameters: parametersFunctions.calculateParams(inputStructure),
        currentLoop: currentLoopFunctions.calculateParams(inputStructure),
        speedLoop: speedLoopFunctions.calculateParams(inputStructure),
        positionLoop: positionLoopFunctions.calculateParams(inputStructure),
        sensorless: sensorlessFunctions.calculateParams(inputStructure)
    }
}