<template>
  <section ref="outputFileCanvas" v-if="visible" :data="setContents()">
    <div class="row">
      <div class="col-1"></div>
      <div class="col"> 
        <div class="row d-inline-block">
          <span ref="outputFileName" class="text-uppercase fw-bold"
            >File name:</span
          >
          <span ref="outputFileName" class="text-uppercase">
            {{ outFile.name }}
          </span>
        </div>
        <br />
        <div class="row d-inline-block">
          <span ref="outputFileDate" class="text-uppercase fw-bold">Date:</span>
          <span ref="outputFileDate" class="text-uppercase">
            {{ outFile.date }}
          </span>
        </div>
        <br />
        <div class="row d-inline-block">
          <span ref="outputFileDescription" class="text-uppercase fw-bold"
            >Descripion:</span
          >
          <span ref="outputFileDescription" class="text-uppercase">
            {{ outFile.description }} 
          </span>
        </div>
      </div>
    </div>
    <hr />
    <div class="row scroller">
      <div class="col">
        <div ref="outputFileContents" class="wrapOutput">
          <div v-html="outFile.contents" />
        </div>
      </div>
    </div>
  </section>
</template>

<script>
export default {
  name: "OutputFileCanvas",
  props: ["visible", "calculatedContents"],
  data() {
    return {
      outFile: {
        name: "",
        date: "",
        description: "",
        contents: "Default comment.",
      },
    };
  },
  methods: {
    setContents() {
      if (typeof this.calculatedContents !== "undefined") {
        this.outFile.contents =
          this.calculatedContents.generateContentsToSave(true);
        this.motorId = this.calculatedContents.motorId;
        this.motorDescription = this.calculatedContents.description;
        this.outFile.name = this.calculatedContents.path;
        this.outFile.description = this.calculatedContents.description;
        this.outFile.date = this.calculatedContents.date;
      }
    },
  },
};
</script>