import { formatNumber } from "../utils";

export class HeaderFile {
    constructor(path, name) {
        this.path = path;
        this.name = name;
        this.copyright = "";
        this.date = "";
        this.motorId = "";
        this.description = "";
        this.values = "";
        this.contents = "";
        this.userInput = "";
    }

    toString() {
        return JSON.stringify(this, null, 4);
    }

    generateContentsToSave(toHtml) {

        const formatMacro = (field) => {
            const formatting = field.formatting;
            return formatting.prefix === "" && formatting.suffix === "" ? field.value : formatNumber(field.value, 6);
        }

        const formatUserInput = (input) => {
            const lines = input.split("\n");
            var formatted = '<div class="comments">';
            formatted += lines[0];
            formatted += "</div>";
            /// TODO: format this if only #define A 1 format is allowed 
            const user = lines.slice(1, -1);
            user.forEach((line) => {
                if (!line.startsWith("#define") || !toHtml) {
                    formatted += line + "\n";
                } else {
                    const chars = line.split(" ");
                    formatted += '<div class="defines">';
                    formatted += chars[0];
                    formatted += "</div> ";
                    formatted += chars.slice(1).join(" ");
                }
            })
            formatted += "\n";
            // formatted += lines.slice(1, -2).join("\n");
            formatted += '<div class="comments">';
            formatted += lines[lines.length - 1];
            formatted += "</div>";
            return formatted;
        }

        if (this.userInput === "") {
            this.userInput = "/* USER INPUT START */\n";
            this.userInput += "/* USER INPUT END */\n";
        }

        var code = "";
        if (toHtml) {
            code += '<div class="comments">';
        }
        code += this.copyright;
        code += "\n\n";
        code += "/*\n";
        code += "    * FILE NAME: " + this.path + "\n";
        code += "    * DATE: " + this.date + "\n";
        code += "*/\n\n";
        code += "/*\n";
        code += JSON.stringify(this.values, null, 4);
        code += "\n*/\n\n";
        code += "/*\n";
        code += JSON.stringify({
            motorName: this.motorId,
            motorDescription: this.description
        }, null, 4);
        code += "\n*/\n\n";
        if (toHtml) {
            code += "</div>";
            code += '<div class="defines">';
        }
        code += "#ifndef __M1_PMSM_APPCONFIG_H \n";
        code += "#define __M1_PMSM_APPCONFIG_H \n\n";
        if (toHtml) {
            code += "</div>";
        }
        Object.keys(this.contents).forEach((entry) => {
            if (toHtml) {
                code += '<div class="comments">';
            }
            code += "/* " + entry.toUpperCase() + "*/\n";
            if (toHtml) {
                code += "</div>";
            }
            const fields = this.contents[entry];
            Object.keys(fields).forEach((key) => {
                const field = fields[key];
                const value = field.value !== "" ? field.formatting.prefix + "(" + formatMacro(field) + field.formatting.suffix + ")" : "";
                if (toHtml) {
                    code += '<div class="defines">';
                    code += "#define ";
                    code += "</div>";
                    code += field.varName + " " + value + "\n";
                } else {
                    code += "#define " + field.varName + " " + value + "\n";
                }
            });
        });
        if (toHtml) {
            code += formatUserInput(this.userInput);
            code +=
                '<div class="defines">' +
                "#endif" +
                "</div>" +
                '<div class="comments">' +
                "/* __M1_PMSM_APPCONFIG_H */" +
                "</div>" +
                "\n";
        } else {
            code += this.userInput;
            code += "\n#endif /* __M1_PMSM_APPCONFIG_H */\n";
        }
        return code;
    }
}