<template>
  <div class="container-fluid display-grid">
    <div class="connectivity">
      <strong v-if="isOffline">
        No internet connection. CSS and icons may not be properly loaded.
      </strong>
    </div>
    <MainCanvas />
    <NavbarTop />
  </div>
</template>

<script>
import NavbarTop from "./components/NavbarTop.vue";
// import NavbarBottom from "./components/NavbarBottom.vue";
import MainCanvas from "./components/MainCanvas.vue";

export default {
  name: "App",
  components: {
    NavbarTop,
    MainCanvas,
    // NavbarBottom,
  },
  data() {
    return {
      isOffline: (() => {
        return !window.navigator.onLine;
      })(),
    };
  },
  mounted: function () {
    const thisRef = this;
    window.addEventListener("online", () => {
      thisRef.isOffline = false;
    });
    window.addEventListener("offline", () => {
      thisRef.isOffline = true;
    });
    window.addEventListener("error", (err) => {
      console.log("Error: ", JSON.stringify(err, ["message", "arguments", "type", "name"]));
    })
  },
};
</script>

<style>
@import "./mcat.css"
</style>

