<template>
  <div class="row">
    <div class="btn-group-vertical btn-group-justified">
      <button
        v-for="item in buttons"
        :key="item.buttonId"
        :id="item.buttonId"
        :class="'btn btn-link btn-block m-1 border-bottom btn-menu ' + item.className"
        v-show="item.visible"
        @click="clicked(item.buttonId)"
      >
        {{ item.buttonName }}
      </button>
    </div>
  </div>
</template>

<script>
export default {
  name: "ButtonsMenu",
  props: ["buttonVisible"],
  data() {
    return {
      buttons: [
        {
          className: "bg-primary text-white",
          buttonId: "applicationConcept",
          buttonName: "Application concept",
          visible: true,
        },
        {
          className: "",
          buttonId: "mid",
          buttonName: "Motor parameters identification (MID)",
          visible: true,
        },
        {
          className: "",
          buttonId: "parameters",
          buttonName: "Parameters",
          visible: true,
        },
        {
          className: "",
          buttonId: "currentLoop",
          buttonName: "Current loop",
          visible: true,
        },
        {
          className: "",
          buttonId: "speedLoop",
          buttonName: "Speed loop",
          visible: true,
        },
        {
          className: "",
          buttonId: "positionLoop",
          buttonName: "Servo Control",
          visible: true,
        },
        {
          className: "",
          buttonId: "sensorless",
          buttonName: "Sensorless",
          visible: true,
        },
        {
          className: "",
          buttonId: "outputFile",
          buttonName: "Output file",
          visible: true,
        },
        {
          className: "",
          buttonId: "onlineUpdate",
          buttonName: "Online update",
          visible: true,
        },
        {
          className: "",
          buttonId: "developerMode",
          buttonName: "Developer mode",
          /* CHANGE BELOW VARIABLE TO TRUE IF YOU ARE A FUTURE DEVELOPER AND WISH TO RUN AUTOMATED TESTS */
          visible: false,
        },
      ],
    };
  },
  methods: {
    clicked(arg) {
      const bgColor = "bg-primary text-white";
      this.buttons.forEach((button) => {
        if (arg === button.buttonId) {
          button.className = bgColor;
        } else {
          button.className = "";
        }
      });
      this.$emit("button-was-clicked", arg);
    },
  },
  watch: {
    buttonVisible: function (newVal) {
      if (newVal) {
        const id = newVal.id;
        const value = newVal.value;
        // console.log(id, value);
        this.buttons.forEach((button) => {
          if (button.buttonId === id) {
            button.visible = value;
          }
        });
      }
    }
  }
};
</script>