  methods: {
    setData(id, value, type) {
      const compareValues = (server, computed) => {
        return (
          Number.parseFloat(server).toPrecision(6) ===
          Number.parseFloat(computed).toPrecision(6)
        );
      };
      const formatValue = (value, parameterId) => {
        let number = Number.parseFloat(value);
        if (!isNaN(number)) {
          // Apply scaling for display if parameter has scaling configured
          const scaling = getScaling(parameterId);
          if (scaling !== 1) {
            number = toDisplayValue(parameterId, number);
          }
          
          if (Number.isInteger(number)) {
            return number;
          } else if (!Number.isInteger(number) && !isNaN(number)) {
            try {
              const precision = number.toString().split(".")[1].length;
              return precision < 6 ? number : number.toPrecision(6);              
            } catch (error) {
              return number;
            }
          }
        }
        return value;
      };
      
      Object.keys(this.rows).forEach((row) => {
        const fields = this.rows[row].columns[1].contents;
        const server = this.rows[row].columns[2].contents;
        const compute = this.rows[row].columns[3].contents;
        Object.keys(fields).forEach((index) => {
          if (fields[index].mainId === id) {
            if (type === this.enums.SERVER) {
              server[index].value = formatValue(value, id);
            } else if (type === this.enums.COMPUTE) {
              compute[index].value = formatValue(value, id);
            }
          }
          setTimeout(() => {
            if (!compareValues(server[index].value, compute[index].value)) {
              fields[index].className += " nxp-orange opacity-75";
              server[index].className += " nxp-orange opacity-75";
              compute[index].className += " nxp-orange opacity-75";
            } else {
              fields[index].className = fields[index].className.replaceAll(
                " nxp-orange opacity-75",
                ""
              );
              server[index].className = server[index].className.replaceAll(
                " nxp-orange opacity-75",
                ""
              );
              compute[index].className = server[index].className.replaceAll(
                " nxp-orange opacity-75",
                ""
              );
            }
          }, 100);
        });
      });
    },
  },
  watch: {
    serverValue: function (newVal) {
      if (newVal && newVal.value !== "") {
        // console.log(newVal);
        this.setData(newVal.id, newVal.value, this.enums.SERVER);
      }
    },
    computedValue: function (newVal) {
      if (newVal && newVal.value !== "") {
        // console.log(newVal);
        this.setData(newVal.id, newVal.value, this.enums.COMPUTE);
      }
    },
    renderField: function(newVal) {
      if (newVal) {
        const id = newVal.id;
        const value = newVal.value;
        const rows = {
          "group": 0,
          "parameters": 1,
          "currentLoop": 2,
          "speedLoop": 3,
          "sensors": 4,
          "sensorless": 5  
        };
        if (typeof rows[id] !== "undefined") {
          const index = rows[id];
          this.rows[index].render = value;
        }
      }
    }
  },
