<template>
  <hr class="bg-white" />
  <div class="row">
    <ManagerMenu
      @button-manager-was-clicked="performAction"
      @motor-description-changed="updateMotorData"
      :inFiles="inputFile"
    />
    <hr class="bg-white" />
  </div>

  <div class="row">
    <div class="col-sm-2">
      <div class="row">
        <div :class="'alert ' + boardInfo.class" role="alert">
          {{ boardInfo.boardId }} {{ boardInfo.errorMessage }}
        </div>
      </div>
      <div class="row">
        <div class="alert alert-dark" role="alert">
          Chosen file: {{ defaultFile.name }}
          <br />
          Motor ID: {{ defaultFile.motorId }}
        </div>
      </div>
      <ButtonsMenu
        @button-was-clicked="showCanvas"
        :devMode="devMode"
        :buttonVisible="buttonVisible"
      />
    </div>
    <div class="col" id="mainCanvas">
      <CatCanvas :visible="visibility.catVisible" />
      <ApplicationConceptCanvas 
        :visible="visibility.applicationConceptVisible" 
        />
      <MidCanvas 
        :visible="visibility.midVisible" 
        :midOutputs="outputs.midOuts"
        @value-was-sent="setValue"
        @freemaster-update-request="updateFreeMasterVariable"
        @test-data-was-sent="sendMidDevData" 
        @user-action-request="performUserAction" 
        :needData="devMode.needData"
        :reloadData="reloadData.midReload" 
        :limits="limits.mid" 
        :renderField="renderField.mid"
        :appState="userButtons.mid.appState" 
        :midMeasType="userButtons.mid.midMeasType" 
        :midState="userButtons.mid.midState" 
        :midFinishedMeas="userButtons.mid.midFinishedMeas" 
        :midFaultsGlobal="userButtons.mid.midFaultsGlobal"
        :midFaultsPp="userButtons.mid.midFaultsPp"
        :midFaultsEl="userButtons.mid.midFaultsEl"
        :midFaultsMech="userButtons.mid.midFaultsMech"
        :diagFaultsCaptured="userButtons.mid.diagFaultsCaptured"
        :diagFaultsPending="userButtons.mid.diagFaultsPending"
        :M1DiagFaultsPending="userButtons.mid.M1DiagFaultsPending"
        :M1AppState="userButtons.mid.M1AppState"
        :midPpState="userButtons.mid.midPpState"
        :midElState="userButtons.mid.midElState"
        :midMechState="userButtons.mid.midMechState"
      />
      <ParametersCanvas 
        :visible="visibility.parametersVisible" 
        :parametersOutputs="outputs.parametersOuts"
        @value-was-sent="setValue" 
        @freemaster-update-request="updateFreeMasterVariable"
        @test-data-was-sent="sendParamsDevData" 
        :needData="devMode.needData"
        :reloadData="reloadData.parametersReload" 
        :limits="limits.parameters" 
        :renderField="renderField.parameters" 
      />
      <CurrentLoopCanvas 
        :visible="visibility.currentLoopVisible" 
        :currentLoopOutputs="outputs.currentLoopOuts"
        @value-was-sent="setValue" 
        @test-data-was-sent="sendCurrentLoopDevData" 
        :needData="devMode.needData"
        :reloadData="reloadData.currentLoopReload" 
        :limits="limits.currentLoop"
        :renderField="renderField.currentLoop"
      />
      <SpeedLoopCanvas 
        :visible="visibility.speedLoopVisible" 
        :speedLoopOutputs="outputs.speedLoopOuts"
        @value-was-sent="setValue" 
        @test-data-was-sent="sendSpeedLoopDevData" 
        :needData="devMode.needData"
        :reloadData="reloadData.speedLoopReload" 
        :limits="limits.speedLoop" 
        :renderField="renderField.speedLoop" 
      />
      <PositionLoopCanvas 
        :visible="visibility.positionLoopVisible" 
        :positionLoopOutputs="outputs.positionLoopOuts"
        @value-was-sent="setValue" 
        @test-data-was-sent="sendPositionLoopDevData" 
        :needData="devMode.needData"
        :reloadData="reloadData.positionLoopReload" 
        :renderField="renderField.positionLoop" 
      />
      <SensorlessCanvas 
        :visible="visibility.sensorlessVisible" 
        :sensorlessOutputs="outputs.sensorlessOuts"
        @value-was-sent="setValue" 
        @test-data-was-sent="sendSensorlessDevData" 
        :needData="devMode.needData"
        :reloadData="reloadData.sensorlessReload" 
        :limits="limits.sensorless" 
        :renderField="renderField.sensorless" 
      />
      <OnlineUpdateCanvas 
        :visible="visibility.onlineUpdateVisible" 
        :serverValue="onlineUpdate.serverValue"
        :computedValue="onlineUpdate.computedValue" 
        :renderField="renderField.onlineUpdate" 
      />
      <OutputFileCanvas 
        :visible="visibility.outputFileVisible" 
        :calculatedContents="defaultFile" 
      />
      <GridDesignCanvas :visible="visibility.gridDesignVisible" />
      <DeveloperModeCanvas 
        :visible="visibility.developerModeVisible" 
        @testing-started="showData"
        :midData="devMode.midDevData" 
        :parametersData="devMode.parametersDevData"
        :currentLoopData="devMode.currentLoopDevData" 
        :speedLoopData="devMode.speedLoopDevData"
        :positionLoopData="devMode.positionLoopDevData" 
        :sensorlessData="devMode.sensorlessDevData"
        :mainCanvasData="devMode.mainCanvasDevData" 
      />
    </div>
  </div>
  <hr class="bg-white" />
  <div
    class="toast nxp-toast text-white bg-primary border-0 text-nowrap w-auto"
    style="z-index: 10"
    role="alert"
    aria-live="assertive"
    aria-atomic="true"
    ref="actionToast"
    data-bs-autohide="false"
  >
    <div class="toast-header m-1">
      <strong class="me-auto">Action in progress</strong>
    </div>
    <div class="toast-body">
      {{ actionDescription }}
    </div>
  </div>

  <div
    class="toast nxp-toast text-white bg-danger border-0 text-nowrap w-auto"
    style="z-index: 10"
    role="alert"
    aria-live="assertive"
    aria-atomic="true"
    ref="errorToast"
    data-bs-autohide="false"
  >
    <div class="toast-header">
      <strong class="me-auto">Error</strong>
    </div>
    <div class="toast-body">
      {{ errorMessage }}
    </div>
  </div>
</template>

<script>
import { Toast } from "bootstrap";
import CatCanvas from "./playground/CatCanvas.vue";
import GridDesignCanvas from "./playground/GridDesignCanvas.vue";
import ApplicationConceptCanvas from "./ApplicationConceptCanvas.vue";
import MidCanvas from "./MidCanvas.vue";
import ParametersCanvas from "./ParametersCanvas.vue";
import CurrentLoopCanvas from "./CurrentLoopCanvas.vue";
import SpeedLoopCanvas from "./SpeedLoopCanvas.vue";
import PositionLoopCanvas from "./PositionLoopCanvas.vue";
import SensorlessCanvas from "./SensorlessCanvas.vue";
import OnlineUpdateCanvas from "./OnlineUpdateCanvas";
import OutputFileCanvas from "./OutputFileCanvas.vue";
import DeveloperModeCanvas from "./developer/DeveloperModeCanvas.vue";
import ButtonsMenu from "./ButtonsMenu.vue";
import ManagerMenu from "./ManagerMenu.vue";
import * as mainCanvas from "../functions/mainCanvas";
//import * as userFunctions from "../functions/userFunctions";
import { midUserButtonHandler, midDeactivateMidFunction } from "../functions/userFunctions";
import * as loadFunctions from "../logic/load";
import {
  mid,
  parameters,
  currentLoop,
  speedLoop,
  positionLoop,
  sensorless,
} from "../logic/model/inputFields";
import { buildStructure, getMainFieldById } from "../logic/utils";
import * as osPath from "path";
import { HeaderFile } from "../logic/model/file";

export default {
  name: "MainCanvas",
  components: {
    CatCanvas,
    GridDesignCanvas,
    ButtonsMenu,
    ApplicationConceptCanvas,
    MidCanvas,
    ParametersCanvas,
    CurrentLoopCanvas,
    SpeedLoopCanvas,
    PositionLoopCanvas,
    SensorlessCanvas,
    OnlineUpdateCanvas,
    OutputFileCanvas,
    DeveloperModeCanvas,
    ManagerMenu,
  },
  data() {
    return {
      actionToast: "",
      errorToast: "",
      boardInfo: {
        boardId: "",
        class: "",
        errorMessage: "",
      },
      setup: "",
      defaultFile: "",
      m1PmsmFile: "m1_pmsm_appconfig.h",
      previousFreeMasterValues: {},
      generatedContents: "",
      isWrong: false,
      pcmStructure: "",
      defaultPcmPath: "",
      errorMessage: "",
      actionIsPerformed: false,
      actionDescription: "",
      buttonVisible: "",
      inputFile: "",
      inputFiles: [],
      devMode: {
        needData: false,
        midDevData: "",
        parametersDevData: "",
        currentLoopDevData: "",
        speedLoopDevData: "",
        positionLoopDevData: "",
        sensorlessDevData: "",
        mainCanvasDevData: "",
      },
      onlineUpdate: {
        serverValue: "",
        computedValue: "",
      },
      reloadData: {
        midReload: "",
        parametersReload: "",
        currentLoopReload: "",
        speedLoopReload: "",
        positionLoopReload: "",
        sensorlessReload: "",
      },
      visibility: {
        catVisible: false,
        applicationConceptVisible: true,
        midVisible: false,
        parametersVisible: false,
        currentLoopVisible: false,
        speedLoopVisible: false,
        positionLoopVisible: false,
        sensorlessVisible: false,
        outputFileVisible: false,
        onlineUpdateVisible: false,
        gridDesignVisible: false,
        developerModeVisible: false,
      },
      outputs: {
        midOuts: "",
        parametersOuts: "",
        currentLoopOuts: "",
        speedLoopOuts: "",
        positionLoopOuts: "",
        sensorlessOuts: "",
      },
      limits: {
        mid: "",
        parameters: "",
        speedLoop: "",
        sensorless: "",
        positionLoop: "",
        currentLoop: "",
      },
      outputFileContents: {
        fileName: "",
        fileDate: "",
        fileDesc: "",
        fileContents: "",
        userInputContents: "",
      },
      generate: {
        mid: true,
        parameters: true,
        currentLoop: true,
        speedLoop: true,
        positionLoop: true,
        sensorless: true,
      },
      renderField: {
        mid: "",
        parameters: "",
        currentLoop: "",
        speedLoop: "",
        sensorless: "",
        positionLoop: "",
        onlineUpdate: "",
      },
      userButtons: {
        mid: {
          appState: '',
          midMeasType: '',
          midState: "",
          midFinishedMeas: "",
          midFaultsGlobal: "",
          midFaultsPp: "",
          midFaultsEl: "",
          midFaultsMech: "",
          diagFaultsCaptured: 0,
          diagFaultsPending: 0,
          M1DiagFaultsPending: 0,
          M1AppState: 2,
          midPpState: "",
          midElState: "",
          midMechState: "",
        },
      },
      mid: mid,
      parameters: parameters,
      speedLoop: speedLoop,
      currentLoop: currentLoop,
      positionLoop: positionLoop,
      sensorless: sensorless,
    };
  },
  methods: {
    showCanvas(e) {
      var visibility = this.visibility;
      Object.keys(visibility).forEach(function (key) {
        if (key.includes(e)) {
          visibility[key] = true;
        } else {
          visibility[key] = false;
        }
      });
    },
    setSettings() {
      /**
       * bEncVer == 1
       * Enable visibility Sensors tab, which is used only for encoder examples
       * Enable visibility PL_Kp output parameter in the Speed loop tab
       * Enable generate #define for outputs from Sensors tab
       * bEncVer == 0
       * Disable visibility Sensors tab
       * Disable visibility PL_Kp
       * Disable generate #define for outputs from Sensors tab
       */

      /*

      this.pcmStructure.readVariable("Feature Encoder", (data) => {
        if (typeof data !== "undefined" && data.formatted !== "") {
          const encoder = Number.parseInt(data.formatted);
          if (encoder === 1) 
          {

            this.buttonVisible = {
              id: "sensors",
              value: true,
            };
            this.generate.sensors = true;
            this.renderField.onlineUpdate = {
              id: "sensors",
              value: true,
            };

          } 
          else 
          {

            this.buttonVisible = {
              id: "sensors",
              value: false,
            };
            this.generate.sensors = false;
            this.renderField.onlineUpdate = {
              id: "sensors",
              value: false,
            };
            
          }


          if (encoder === 1) 
          {

            this.buttonVisible = {
              id: "positionLoop",
              value: true,
            };
            this.generate.positionLoop = true;
            this.renderField.onlineUpdate = {
              id: "positionLoop",
              value: true,
            };

          } 
          else 
          {
            this.buttonVisible = {
              id: "positionLoop",
              value: false,
            };
            this.generate.positionLoop = false;
            this.renderField.onlineUpdate = {
              id: "positionLoop",
              value: false,
            };
          }


        }
      });

      */
    },
    setSingleValue(id, value) {
      var found = false;
      const thisRef = this;
      buildStructure(this.getData(), function (canvas, field) {
        if (field.id === id) {
          field.currentValue = value;
          if (typeof field.manualValue !== "undefined") {
            field.manualValue = value;
          }
          if (field.values[field.values.length - 1] !== value) {
            field.values.push(value);
          }
          thisRef.setExternalLimits(id, value);
          found = true;
        }
      });
      if (!found) {
        console.error("Wrong id: ", id, " with value: ", value);
      }
    },
    setExternalLimits(id, value) {
      const setRange = (id, value) => {
        const limitsMap = {
          parametersImax: () => {
            setTimeout(() => {
              this.limits.mid = {
                id: id,
                value: value,
              };
              this.limits.speedLoop = {
                id: id,
                value: value,
              };
              this.limits.sensorless = {
                id: id,
                value: value,
              };
            }, 100);
          },
          parametersNover: () => {
            setTimeout(() => {
              this.limits.mid = {
                id: id,
                value: value,
              };
              this.limits.sensorless = {
                id: id,
                value: value,
              };
            }, 100);
          },
          parametersNmin: () => {
            setTimeout(() => {
              this.limits.sensorless = {
                id: id,
                value: value,
              };
            }, 100);
          },
          currentLoopSampleTime: () => {
            setTimeout(() => {
              this.limits.parameters = {
                id: id,
                value: value,
              };
            }, 100);
          },
        };
        if (typeof limitsMap[id] !== "undefined") {
          limitsMap[id]();
        }
      };
      setRange(id, value);
    },
    setTunning() {
      const slkp = getMainFieldById(this.getData(), "speedLoopSLKp");
      const slki = getMainFieldById(this.getData(), "speedLoopSLKi");
      const manualConstantTunning = getMainFieldById(
        this.getData(),
        "speedLoopManualConstantTunning"
      );
      const setValues = (field) => {
        setTimeout(() => {
          this.outputs["speedLoopOuts"] = {
            id: field.id,
            value: field.currentValue,
          };
        }, 100);
        field.outputFile.value = field.currentValue;
        this.generatedContents = this.generateOutputFile(this.defaultFile);
      };
      if (manualConstantTunning.currentValue) {
        slkp.currentValue = slkp.manualValue;
        slki.currentValue = slki.manualValue;
      } else {
        slkp.currentValue = slkp.computedValue;
        slki.currentValue = slki.computedValue;
      }
      setValues(slkp);
      setValues(slki);
    },
    setValue(e) {
      var id = e[0];
      var value = e[1];
      this.setSingleValue(id, value, "");
      this.generatedContents = this.generateOutputFile(this.defaultFile);
    },

    /* start: SEND DATA FROM CANVASES TO DEVELOPER MODE */
    /**
     * simplifies grid structure for data manipulation. If new *section* is added / deleted it has to be manually changed
     * @param {none}
     * @returns {object} grid data divided into input / output group
     */
    getData() {
      return {
        mid: this.mid,
        parameters: this.parameters,
        currentLoop: this.currentLoop,
        speedLoop: this.speedLoop,
        positionLoop: this.positionLoop,
        sensorless: this.sensorless,
      };
    },
    sendMidDevData(e) {
      this.devMode.midDevData = e;
    },
    sendParamsDevData(e) {
      this.devMode.parametersDevData = e;
    },
    sendCurrentLoopDevData(e) {
      this.devMode.currentLoopDevData = e;
    },
    sendSpeedLoopDevData(e) {
      this.devMode.speedLoopDevData = e;
    },
    sendPositionLoopDevData(e) {
      this.devMode.positionLoopDevData = e;
    },
    sendSensorlessDevData(e) {
      this.devMode.sensorlessDevData = e;
    },
    showData() {
      this.devMode.needData = true;
      this.devMode.mainCanvasDevData = this.getData();
    },
    /* end: SEND DATA FROM CANVASES TO DEVELOPER MODE */
    setFreeMasterSubscribedValue(freeMasterVar, value) {
      // Helper function to determine output key based on field ID
      const getOutputKeyForField = (fieldId) => {
        if (fieldId.startsWith('mid'         )) return 'midOuts';
        if (fieldId.startsWith('parameters'  )) return 'parametersOuts';
        if (fieldId.startsWith('currentLoop' )) return 'currentLoopOuts';
        if (fieldId.startsWith('speedLoop'   )) return 'speedLoopOuts';
        if (fieldId.startsWith('positionLoop')) return 'positionLoopOuts';
        if (fieldId.startsWith('sensorless'  )) return 'sensorlessOuts';
        if (fieldId.startsWith('sensors'     )) return 'sensorsOuts';
        return 'midOuts'; // default fallback
      };

      /* Priority-based field mappings (lower number = lower priority, 0 = lowest) */
      const MID_MEAS_PARAM_MAP = {
        // Measured parameters (PRIORITY 0 - lowest)
        "MID: Measured Pp":      { priority: 0, targets: ["midPolePairIAPp",    "parametersPp" ] },
        "MID: Measured Rs":      { priority: 0, targets: ["midElParamMeasRs",   "parametersRs" ] },
        "MID: Measured Ld":      { priority: 0, targets: ["midElParamMeasLd",   "parametersLd" ] },
        "MID: Measured Lq":      { priority: 0, targets: ["midElParamMeasLq",   "parametersLq" ] },
        "MID: Measured Udt":     { priority: 0, targets: ["midElParamMeasUdt"                  ] },
        "MID: Measured Ke":      { priority: 0, targets: ["midMechParamMeasKe",                ] },
        "MID: Measured Kt":      { priority: 0, targets: ["midMechParamMeasKt", "parametersKt" ] },
        "MID: Measured J":       { priority: 0, targets: ["midMechParamMeasJ",  "parametersJ"  ] },
        "MID: Measured B":       { priority: 0, targets: ["midMechParamMeasB"                  ] },
        "MID: Measured A":       { priority: 0, targets: ["midMechParamMeasA"                  ] },
        
        // Known parameters (PRIORITY 1 - values set by user)
        "MID: Known Param Pp":   { priority: 1, targets: ["midPolePairIAPp",    "parametersPp" ] },
        "MID: Known Param Rs":   { priority: 1, targets: ["midElParamMeasRs",   "parametersRs" ] },
        "MID: Known Param Ld":   { priority: 1, targets: ["midElParamMeasLd",   "parametersLd" ] },
        "MID: Known Param Lq":   { priority: 1, targets: ["midElParamMeasLq",   "parametersLq" ] },
        "MID: Known Param Udt":  { priority: 1, targets: ["midElParamMeasUdt"                  ] },
      };

      // State variable mappings
      const MID_CONTROL_MAP = {
        'APP: State':                  'appState',
        'MID: Measurement Type':       'midMeasType',
        'MID: State':                  'midState',
        'MID: Finished measurements':  'midFinishedMeas',
        'MID: Global faults':          'midFaultsGlobal',
        'MID: Pp faults':              'midFaultsPp',
        'MID: El faults':              'midFaultsEl',
        'MID: Mech faults':            'midFaultsMech',
        'DIAG: Fault Pending':         'diagFaultsPending',
        'DIAG: Fault Captured':        'diagFaultsCaptured',
        'M1 Fault Pending':            'M1DiagFaultsPending',
        'M1 Application State':        'M1AppState',
        'MID: Pp Meas Status':         'midPpState',
        'MID: El Meas Status':         'midElState',
        'MID: Mech Meas Status':       'midMechState',
      };

      const updateParameterWithPriority = (fieldId, baseValue, outputKey, priority, delay = 100) => {
        const parameter = getMainFieldById(this.getData(), fieldId);
        if (!parameter) return;

        // Initialize priority tracking properties on the parameter if not exists
        if (typeof parameter.lastKnownValue === 'undefined') {
          parameter.lastKnownValue = null;
        }
        if (typeof parameter.lastMeasuredValue === 'undefined') {
          parameter.lastMeasuredValue = null;
        }
        // Initialize currentPriority as 0 if not set (lowest priority)
        if (typeof parameter.currentPriority === 'undefined') {
          parameter.currentPriority = 0;
        }

        // Store the value based on priority level
        if (priority === 0) {
          parameter.lastMeasuredValue = baseValue;
        } else if (priority >= 1) {
          parameter.lastKnownValue = baseValue;
        }

        // Determine if we should update based on priority
        const shouldUpdate = () => {
          // Always update if incoming priority is higher than current
          if (priority > parameter.currentPriority) {
            return true;
          }
          
          // If incoming priority equals current priority, update
          if (priority === parameter.currentPriority) {
            return true;
          }
          
          // If incoming priority is lower, only update if:
          // 1. Current high priority value is zero/null/undefined AND
          // 2. We have a valid incoming value
          if (priority < parameter.currentPriority) {
            const currentHighPriorityValue = priority === 0 ? parameter.lastKnownValue : parameter.lastMeasuredValue;
            return (currentHighPriorityValue === 0 || currentHighPriorityValue === null || currentHighPriorityValue === undefined) &&
                  (baseValue !== 0 && baseValue !== null && baseValue !== undefined);
          }
          
          return false;
        };

        if (shouldUpdate()) {
          // Handle high priority values (priority >= 1)
          if (priority >= 1) {
            if (baseValue !== 0 && baseValue !== null && baseValue !== undefined) {
              // Valid high priority value - update with this priority
              parameter.currentPriority = priority;
              parameter.currentValue = baseValue;
              
              setTimeout(() => {
                this.outputs[outputKey] = {
                  id: parameter.id,
                  value: baseValue,
                };
              }, delay);
              // console.log(`Updated ${fieldId} with priority: "${priority}" value: "${baseValue}"`);
            } else if (baseValue === 0 && parameter.lastMeasuredValue !== null) {
              // High priority value is zero, fallback to measured if available
              parameter.currentPriority = 0;
              parameter.currentValue = parameter.lastMeasuredValue;
              
              setTimeout(() => {
                this.outputs[outputKey] = {
                  id: parameter.id,
                  value: parameter.lastMeasuredValue,
                };
              }, delay);
              // console.log(`Updated ${fieldId} with fallback measured value: ${parameter.lastMeasuredValue}`);
            }
          } else if (priority === 0) {
            // Measured parameter update (priority 0)
            parameter.currentPriority = 0;
            parameter.currentValue = baseValue;
            
            setTimeout(() => {
              this.outputs[outputKey] = {
                id: parameter.id,
                value: baseValue,
              };
            }, delay);
            // console.log(`Updated ${fieldId} with priority: "${priority}" value: "${baseValue}"`);
          }
        } else {
          // console.log(`Skipped updating ${fieldId} - higher priority value exists (current priority: ${parameter.currentPriority}, incoming priority: ${priority})`);
        }
      };

      // Handle MID control using mapping
      if (MID_CONTROL_MAP[freeMasterVar]) {
        this.userButtons.mid[MID_CONTROL_MAP[freeMasterVar]] = value;
        return;
      }

      // Handle MID measurements with priority system
      else if (MID_MEAS_PARAM_MAP[freeMasterVar]) {
        const mapping = MID_MEAS_PARAM_MAP[freeMasterVar];
        const { priority, targets } = mapping;
        
        // Initialize previousValue if not set
        if (typeof this.previousFreeMasterValues[freeMasterVar] === 'undefined') {
          this.previousFreeMasterValues[freeMasterVar] = value;
          // Don't process on first subscription - let loaded values stay
          return;
        }
        
        // Check if FreeMASTER variable value has actually changed
        const previousValue = this.previousFreeMasterValues[freeMasterVar];
        
        if (previousValue !== value) {
          // FreeMASTER variable changed, update the tracking and process targets
          this.previousFreeMasterValues[freeMasterVar] = value;
          
          targets.forEach((fieldId) => {
            const outputKey = getOutputKeyForField(fieldId);
            updateParameterWithPriority(fieldId, value, outputKey, priority, 100);
          });
        }
        return;
      }

      // Handle other FreeMASTER variables
      else{
        buildStructure(this.getData(), (canvas, field) => {
          if (
            typeof field.freeMaster !== "undefined" &&
            field.freeMaster.varName === freeMasterVar
          ) {
            field.freeMaster.freeMasterValue = value;
            this.onlineUpdate.serverValue = {
              id: field.id,
              value: field.freeMaster.freeMasterValue,
            };
          }
        });
      }
    },
    updateFreeMasterVariable(updateRequest) {
      const { varName, value, fieldId } = updateRequest;
      this.pcmStructure.checkVariable(varName).then(() => {
          this.pcmStructure.writeVariable(varName, value);
          setTimeout(() => {
            this.onlineUpdate.serverValue = {
              id: fieldId,
              value: value,
            };
          }, 100);
        })
      .catch((err) => {
        console.error(`Failed to update FreeMASTER variable "${varName}":`, err.message);
        this.errorMessage = `Cannot update ${varName} on target: ${err.message}`;
        this.errorToast.show();
      });
    },
    /* start: CONTROLLING BUTTONS BAR */
    action(callback) {
      const thisRef = this;
      if (!thisRef.actionIsPerformed) {
        thisRef.actionIsPerformed = true;
        thisRef.actionToast.show();
        callback();
        setTimeout(() => {
          thisRef.actionIsPerformed = false;
          thisRef.actionToast.hide();
        }, 3000);
      } else {
        thisRef.actionDescription = "Waiting for previous action to finish...";
        thisRef.actionToast.show();
        setTimeout(() => {
          this.action(callback);
        }, 300);
      }
    },
    setParsedData(contents) {
      const data = this.getData();
      const times = {
        "currentLoopSampleTime": "M1 Fast Control Loop Frequency",
        "speedLoopSampleTime": "M1 Slow Control Loop Frequency",
        "positionLoopSampleTime": "M1 Slow Control Loop Frequency",
        "sensorObsrvParSampleTime": "M1 Fast Control Loop Frequency"
      };

      const setValue = (value, field, canvas) => {
        if (typeof field.manualValue !== "undefined") {
          field.manualValue = value;
        }
        field.currentValue = value;
        this.setTunning();
        this.setExternalLimits(field.id, value);
        setTimeout(() => {
          this.reloadData[canvas + "Reload"] = {
            id: field.id,
            value: value,
          };
        }, 100);
      };

      buildStructure(data, (canvas, field) => {
        if (
          typeof contents[canvas] !== "undefined" &&
          typeof contents[canvas][field.id] !== "undefined"
        ) {
          const v = contents[canvas][field.id];
          if (Object.keys(times).includes(field.id)) {
            this.pcmStructure.isCommPortOpen(port => {
              if (port) {
                this.pcmStructure.readVariable(times[field.id], data => {
                  // console.log(field.id, times[field.id]);
                  if (data !== "") {
                    setValue(1 / parseFloat(data.formatted), field, canvas);
                  } else {
                    setValue(v, field, canvas);
                  }
                });
              } else {
                setValue(v, field, canvas);
              }
            });
          } else {
            setValue(v, field, canvas);
          }
        }
        if (
          this.generate[canvas] &&
          typeof field.freeMaster !== "undefined" &&
          field.freeMaster.varName !== ""
        ) {
          setTimeout(() => {
            this.pcmStructure.readVariable(field.freeMaster.varName, (data) => {
              if (data !== "") {
                field.freeMaster.freeMasterValue = data.formatted;
                this.onlineUpdate.serverValue = {
                  id: field.id,
                  value: field.freeMaster.freeMasterValue,
                };
                this.pcmStructure.subscribeVariable(
                  field.freeMaster.varName,
                  (name, value) => {
                    this.setFreeMasterSubscribedValue(name, value);
                  }
                );
              }
            });
          }, 300);
        }
      });
    },
    updateMotorData(target) {
      const name = target[0];
      const motorId = target[1];
      const description = target[2];
      var found = false;
      this.inputFiles.forEach((file) => {
        if (file.name === name) {
          found = true;
          file.motorId = motorId;
          file.description = description;
        }
      });
      if (!found) {
        const newPath = osPath.join(this.defaultPcmPath, name);
        const newFile = new HeaderFile(newPath, name);
        newFile.motorId = motorId;
        newFile.description = description;
        newFile.userInput = this.defaultFile.userInput;
        this.inputFiles.push(newFile);
        newFile.contents = this.generateOutputFile(newFile);
        this.inputFile = newFile;
      }
    },
    performAction(target) {
      const id = target[0];
      const path = target[1];
      switch (id) {
        case "updateTargetButton":
          this.action(() => {
            this.actionDescription = "Updating target...";
            const variables = {};
            buildStructure(this.getData(), (canvas, field) => {
              if (
                this.generate[canvas] &&
                typeof field.freeMaster !== "undefined" &&
                field.freeMaster.varName !== ""
              ) {
                variables[field.freeMaster.varName] = {
                  id: field.id,
                  value: field.freeMaster.value,
                };
              }
            });
            Object.keys(variables).forEach((variable) => {
              if (variables[variable] !== "") {
                this.pcmStructure
                  .checkVariable(variable)
                  .then(() => {
                    this.pcmStructure.writeVariable(
                      variable,
                      variables[variable].value
                    );
                    setTimeout(() => {
                      this.onlineUpdate.serverValue = {
                        id: variables[variable].id,
                        value: variables[variable].value,
                      };
                    }, 100);
                  })
                  .catch((err) => {
                    console.error(err.msg);
                    // thisRef.errorMessage = "Cannot update data on target";
                    // thisRef.errorToast.show();
                  });
              }
            });
          });
          break;
        case "loadFileButton":
          this.action(() => {
            this.actionDescription = "Loading data...";
            var found = false;
            this.inputFiles.forEach((entry) => {
              if (entry.name === path) {
                found = true;
                this.defaultFile = entry;
                const fileName = entry.name;
                const filePath = osPath.join(this.defaultPcmPath, fileName);
                this.setup.createHeaderFile(filePath, fileName, (data) => {
                  if (typeof data !== "undefined") {
                    entry = data;
                    this.defaultFile = data;
                    this.setParsedData(entry.values);
                    this.generatedContents = this.generateOutputFile(
                      this.defaultFile
                    );
                  } else {
                    this.errorMessage =
                      " File: " +
                      fileName +
                      " was corrupted during external edit.";
                    this.errorToast.show();
                  }
                });
              }
            });
            if (!found) {
              this.errorMessage =
                " File: " + path + " not found in the parsed files";
              this.errorToast.show();
            }
          });
          break;
        case "saveFileButton":
          this.action(() => {
            this.actionDescription = "Saving data...";
            var found = false;
            this.inputFiles.forEach((file) => {
              if (file.name === path) {
                found = true;
                file.userInput = this.defaultFile.userInput;
                this.generatedContents = this.generateOutputFile(file);
                if (
                  this.defaultPcmPath === "" &&
                  file.name === "m1_pmsm_appconfig.h"
                ) {
                  const overwritePath = osPath.join(
                    this.defaultPcmPath,
                    file.name
                  );
                  file.path = overwritePath;
                }
                this.pcmStructure.writeOutputFileContents(
                  file.path,
                  this.generatedContents
                );
                this.actionDescription = "Data was saved to: " + file.path;
              }
            });
            if (!found) {
              const newPath = osPath.join(this.defaultPcmPath, path);
              const newFile = new HeaderFile(newPath, path);
              newFile.userInput = this.defaultFile.userInput;
              this.inputFiles.push(newFile);
              this.generatedContents = this.generateOutputFile(newFile);
              this.pcmStructure.writeOutputFileContents(
                newFile.path,
                this.generatedContents
              );
              this.inputFile = newFile;
              this.actionDescription = "Data was saved to: " + newFile.path;
            }
          });
          break;
        default:
          this.errorMessage = "id: " + id + " is invalid";
          this.errorToast.show();
          break;
      }
    },
    performUserAction(target) {
      if (!Array.isArray(target) || target.length < 2) {
        console.warn("Invalid target passed to performUserAction.");
        return;
      }

      const [actionType, midThisRef, ...additionalParams] = target;

      if (typeof actionType === "string") {
        /* Handle function calls */
        const functions = { midDeactivateMidFunction };
        const func = functions[actionType];
        
        if (func) {
          func(this.pcmStructure, this.getData(), midThisRef, ...additionalParams);
        } else {
          console.warn(`Function "${actionType}" not found.`);
        }
      } else if (actionType && typeof actionType === "object") {
        /* Handle button actions */
        midUserButtonHandler(this.pcmStructure, this.getData(), midThisRef, actionType, ...additionalParams);
      } else {
        console.warn("Invalid action type.");
      }
    },
    /* end: CONTROLLING BUTTONS BAR*/

    generateOutputFile(file) {
      const thisRef = this;
      const inputs = {};
      const outputs = {};
      const date = (() => {
        const currentDate = new Date();
        if (file.copyright === "") {
          file.copyright =
            "/*\n" +
            "    * Copyright " +
            currentDate.getFullYear() +
            " NXP \n" +
            "    *\n" +
            "    * SPDX-License-Identifier: BSD-3-Clause \n" +
            "*/\n";
        }
        return (
          currentDate.toDateString() +
          ", " +
          currentDate.toTimeString().split(" ")[0]
        );
      })();
      file.date = date;
      buildStructure(this.getData(), function (canvas, field) {
        if (!Object.keys(inputs).includes(canvas) && thisRef.generate[canvas]) {
          inputs[canvas] = {};
          outputs[canvas] = {};
        }
        if (
          typeof inputs[canvas] !== "undefined" &&
          !Object.keys(inputs[canvas]).includes(field.id) &&
          field.comment
        ) {
          inputs[canvas][field.id] = "";
          if (["speedLoopSLKp", "speedLoopSLKi"].includes(field.id)) {
            inputs[canvas][field.id] = field.manualValue;
          } else {
            inputs[canvas][field.id] = field.currentValue;
          }
        }
        if (
          typeof field.outputFile !== "undefined" &&
          !Object.keys(outputs).includes(field.outputFile.varName) &&
          thisRef.generate[canvas] &&
          field.outputFile.varName !== ""
        ) {
          outputs[canvas][field.id] = field.outputFile;
        }
      });
      file.values = inputs;
      file.contents = outputs;
      return file.generateContentsToSave(false);
    },
  },
  computed: {
    buildInputs() {
      var keys = {};
      buildStructure(this.getData(), function (canvas, field) {
        if (!Object.keys(keys).includes(canvas)) {
          keys[canvas] = {};
        }
        if (!Object.keys(keys[canvas]).includes(field.id)) {
          keys[canvas][field.id] = "";
        }
        keys[canvas][field.id] = field.currentValue;
      });
      return keys;
    },
  },
  watch: {
    buildInputs: {
      deep: true,
      handler(newVal) {
        if (!newVal || !this.defaultFile) {
          return; // Exit early if not ready
        }
        
        try {
          const result = mainCanvas.calculate(newVal);
          const data = this.getData();
          buildStructure(data, (canvas, field) => {
            var out = canvas + "Outs";
            if (typeof field.outputFile !== "undefined") {
              if (
                Object.keys(result[canvas]).includes(field.outputFile.varName)
              ) {
                const computedVal = result[canvas][field.outputFile.varName];
                if (typeof field.computedValue !== "undefined") {
                  field.computedValue = computedVal;
                  this.setTunning();
                } else {
                  if (!isNaN(computedVal)) {
                    field.outputFile.value = computedVal;
                    if (!field.comment) {  // Only emit calculated outputs, not user inputs
                      setTimeout(() => {
                        this.outputs[out] = {
                          id: field.id,
                          value: field.outputFile.value,
                        };
                      }, 100);
                    }
                  }
                }
              } else {
                field.outputFile.value = field.currentValue;
              }
              if (typeof field.freeMaster !== "undefined") {
                field.freeMaster.value = field.outputFile.value;
                setTimeout(() => {
                  this.onlineUpdate.computedValue = {
                    id: field.id,
                    value: field.freeMaster.value,
                  };
                }, 100);
              }
            } else {
              if (typeof field.freeMaster !== "undefined") {
                if (
                  Object.keys(result[canvas]).includes(field.freeMaster.varName)
                ) {
                  const computedVal = result[canvas][field.freeMaster.varName];
                  field.freeMaster.value = computedVal;
                  setTimeout(() => {
                    this.onlineUpdate.computedValue = {
                      id: field.id,
                      value: field.freeMaster.value,
                    };
                  }, 100);
                }
              }
            }
          });
        } catch (error) {
          console.warn('Error in buildInputs watcher:', error);
        }
      },
    },
  },
  /**
   * mounted represents the piece of code that will be executed when page loads. It is an equivalent of $document.onload(() => { // do stuff})
   * In this case a freeMaster script is imported and a connection is initalized.
   * Once it's connected a header file is parsed and all the canvases are filled with default values.
   */
  mounted() {
    console.log("mounted");
    this.actionToast = new Toast(this.$refs.actionToast);
    this.errorToast = new Toast(this.$refs.errorToast);
  // },
  // created() {
    console.log("created");
    console.log("Loading the freeMASTER script...");
    const thisRef = this;
    import("../../public/init.js")
      .then((data) => {
        thisRef.pcmStructure = new data.PcmObject();
        const setup = new loadFunctions.Setup(thisRef.$data);
        thisRef.setup = setup;
        thisRef.pcmStructure.onCommPortStateChanged((data) => {
          if (data) {
            thisRef.pcmStructure.onBoardDetected(() => {
              setTimeout(() => {
                setup.getBoardId((id) => {
                  setup.setBoardId(id);
                  thisRef.errorToast.hide();
                  if (thisRef.defaultPcmPath === "") {
                    var exampleId = "";
                    thisRef.pcmStructure.readVariable("Example ID", (exData) => {
                      if (exData !== "" && typeof exData !== "undefined") {
                        exampleId = exData.formatted;
                      }

                      var userPath1 = "";
                      var userPath2 = "";
                      thisRef.pcmStructure.readVariable("User Path 1", (userPath) => {
                        if (userPath !== "" && typeof userPath !== "undefined") {
                          userPath1 = userPath.formatted;
                        }

                        thisRef.pcmStructure.readVariable("User Path 2", (userPath) => {
                          if (userPath !== "" && typeof userPath !== "undefined") {
                            userPath2 = userPath.formatted;
                          }

                          const paths = setup.buildInputPaths(id, exampleId, userPath1, userPath2);
                          const m1 = setup.getInputPath(paths, 0);
                          m1.then((response) => {
                            readFromPath(response);
                            const dirPath = response
                              .split(osPath.sep)
                              .slice(0, -1)
                              .join(osPath.sep);
                            for (let i = 2; i < 10; i++) {
                              const fileName =
                                "m" + i.toString() + "_pmsm_appconfig.h";
                              const mxFilePath = osPath.join(dirPath, fileName);
                              setup.createHeaderFile(
                                mxFilePath,
                                fileName,
                                (data) => {
                                  if (typeof data !== "undefined") {
                                    thisRef.inputFile = data;
                                    thisRef.inputFiles.push(data);
                                  }
                                }
                              );
                            }
                          }).catch(() => {
                            const defaultPath = osPath.join(
                              "pmsm_float",
                              "mcat",
                              thisRef.m1PmsmFile
                            );
                            console.log("Loading default file: ", defaultPath);
                            setup.createHeaderFile(
                              defaultPath,
                              thisRef.m1PmsmFile,
                              (data) => {
                                if (typeof data !== "undefined") {
                                  thisRef.inputFile = data;
                                  thisRef.defaultPcmPath = "";
                                  thisRef.inputFiles.push(data);
                                  thisRef.setSettings();
                                  setTimeout(() => {
                                    thisRef.defaultFile = data;
                                    thisRef.setParsedData(data.values);
                                    thisRef.generatedContents =
                                      thisRef.generateOutputFile(
                                        thisRef.defaultFile
                                      );
                                  }, 300);
                                } else {
                                  thisRef.errorMessage =
                                    "Cannot open the default file. Check the path: " +
                                    defaultPath +
                                    " if the file is present and is valid. After that refresh your application.";
                                  thisRef.errorToast.show();
                                }
                              }
                            );
                          });
                        });
                      });
                    });
                  }
                });
              }, 500);
            });
          } else {
            setup.setBoardId("");
            thisRef.errorMessage = "Lost connection to board!";
            thisRef.errorToast.show();
          }
        });
        const readFromPath = function (path) {
          const tmp = path.split(osPath.sep);
          const name = tmp[tmp.length - 1];
          thisRef.defaultPcmPath = tmp.slice(0, -1).join(osPath.sep);
          console.log(
            "Found the right freeMASTER path: ",
            thisRef.defaultPcmPath
          );
          setup.createHeaderFile(path, name, (data) => {
            if (typeof data !== "undefined") {
              thisRef.defaultFile = data;
              thisRef.inputFile = data;
              thisRef.inputFiles.push(data);
              thisRef.setSettings();
              setTimeout(() => {
                thisRef.setParsedData(data.values);
                thisRef.generatedContents = thisRef.generateOutputFile(
                  thisRef.defaultFile
                );
              }, 300);
            } else {
              thisRef.errorMessage =
                "Cannot set data => " + path + " is not valid.";
              thisRef.errorToast.show();
            }
          });
        };
        thisRef.pcmStructure.readVariable("Board ID", (data) => {
          var boardId = "";
          var exampleId = "";
          if (data !== "" && typeof data !== "undefined") {
            boardId = data.formatted;
          }
          setup.setBoardId(boardId);
          thisRef.pcmStructure.readVariable("Example ID", (exData) => {
            if (exData !== "" && typeof exData !== "undefined") {
              exampleId = exData.formatted;
            }

            var userPath1 = "";
            var userPath2 = "";
            thisRef.pcmStructure.readVariable("User Path 1", (userPath) => {
              if (userPath !== "" && typeof userPath !== "undefined") {
                userPath1 = userPath.formatted;
              }

              thisRef.pcmStructure.readVariable("User Path 2", (userPath) => {
                if (userPath !== "" && typeof userPath !== "undefined") {
                  userPath2 = userPath.formatted;
                }

                const paths = setup.buildInputPaths(boardId, exampleId, userPath1, userPath2);
                const m1 = setup.getInputPath(paths, 0);
                m1.then((response) => {
                  readFromPath(response);
                  const dirPath = response
                    .split(osPath.sep)
                    .slice(0, -1)
                    .join(osPath.sep);
                  for (let i = 2; i < 10; i++) {
                    const fileName = "m" + i.toString() + "_pmsm_appconfig.h";
                    const mxFilePath = osPath.join(dirPath, fileName);
                    setup.createHeaderFile(mxFilePath, fileName, (data) => {
                      if (typeof data !== "undefined") {
                        thisRef.inputFile = data;
                        thisRef.inputFiles.push(data);
                      }
                    });
                  }
                }).catch(() => {
                  const defaultPath = osPath.join(
                    "pmsm_float",
                    "mcat",
                    thisRef.m1PmsmFile
                  );
                  console.log("Loading default file: ", defaultPath);
                  setup.createHeaderFile(
                    defaultPath,
                    thisRef.m1PmsmFile,
                    (data) => {
                      if (typeof data !== "undefined") {
                        thisRef.inputFile = data;
                        thisRef.defaultPcmPath = "";
                        thisRef.inputFiles.push(data);
                        thisRef.setSettings();
                        setTimeout(() => {
                          thisRef.defaultFile = data;
                          thisRef.setParsedData(data.values);
                          thisRef.generatedContents = thisRef.generateOutputFile(
                            thisRef.defaultFile
                          );
                        }, 300);
                      } else {
                        thisRef.errorMessage =
                          "Cannot open the default file. Check the path: " +
                          defaultPath +
                          " if the file is present and is valid. After that refresh your application.";
                        thisRef.errorToast.show();
                      }
                    }
                  );
                });
              });
            });
          });
        });
        ["APP: State", "MID: Measurement Type", "MID: State", "MID: Finished measurements", "MID: Global faults", "MID: Pp faults", "MID: El faults", "MID: Mech faults", "DIAG: Fault Pending", "DIAG: Fault Captured", "M1 Fault Pending", "M1 Application State", "MID: Pp Meas Status", "MID: El Meas Status", "MID: Mech Meas Status",
         "MID: Known Param Pp", "MID: Known Param Rs", "MID: Known Param Ld", "MID: Known Param Lq", "MID: Known Param Udt", 
         "MID: Measured Pp", "MID: Measured Rs", "MID: Measured Ld", "MID: Measured Lq", "MID: Measured Udt", "MID: Measured Ke", "MID: Measured Kt", "MID: Measured J", "MID: Measured B", "MID: Measured A"
        ].forEach(i => {
          thisRef.pcmStructure.subscribeVariable(i,
            (name, value) => {
              this.setFreeMasterSubscribedValue(name, value);
            })
        })
      })
      .catch((err) => {
        console.log(JSON.stringify(err, ["message", "arguments", "type", "name"]));
      });
  },
};
</script>